import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") ?? None<String>
        let method = request.get("method") ?? None<String>

        if (path == None || method == None) {
            return false
        }

        let validatedPath = path.getOrThrow()
        let validatedMethod = method.getOrThrow()

        if (validatedMethod == "POST" || validatedMethod == "GET") {
            if (this.is_start_with(request_uri: validatedPath)) {
                if (let user = this.get_jwt_user(request: request)) {
                    this.set_current_user_info_and_log(user: user.getOrThrow())
                    return true
                }
            }
        }
        return false
    }

    public func is_start_with(request_uri: String): Bool {
        let prefixes = ["/api", "/login"]
        for (prefix in prefixes) {
            if (request_uri.startsWith(prefix)) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        if (let headers = request.get("headers")) {
            let validatedHeaders = headers.getOrThrow() as HashMap<String, Any>
            if (let auth = validatedHeaders.get("Authorization")) {
                let validatedAuth = auth.getOrThrow() as HashMap<String, Any>
                if (let user = validatedAuth.get("user")) {
                    return Some<HashMap<String, Any>>(user.getOrThrow() as HashMap<String, Any>)
                }
            }
        }
        return None<HashMap<String, Any>>
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        if (let name = user.get("name")) {
            let nameStr = name.getOrThrow() as String
            println("User ${nameStr} accessed the system")
        }
    }
}

import std.math.*

class AreaCalculator {
    let radius: Float64

    public init(radius: Float64) {
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        return PI * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        return 4 * PI * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        return 2 * PI * this.radius * this.radius + 2 * PI * this.radius * height
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        return (angle / (2 * PI)) * PI * this.radius * this.radius
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        return PI * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

