class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        if (parts.size < 3 || parts[0] != "python" || parts[1] != "script.py") {
            return (false, None<HashSet<String>>()) // basic validation
        }

        var i = 2
        var missing_args: Option<HashSet<String>> = None<HashSet<String>>()
        let temp_missing = HashSet<String>()

        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let arg_name = part.substring(2)
                i += 1
                if (i >= parts.size) {
                    arguments.add(arg_name, true) // boolean flag
                } else {
                    let value = parts[i]
                    let converted_value = convert_type(arg_name, value)
                    arguments.add(arg_name, converted_value)
                    i += 1
                }
            } else if (part.startsWith("-")) {
                let arg_name = part.substring(1)
                arguments.add(arg_name, true) // boolean flag
                i += 1
            } else {
                i += 1
            }
        }

        for (arg in required) {
            if (!arguments.contains(arg)) {
                temp_missing.add(arg)
            }
        }

        if (temp_missing.size > 0) {
            missing_args = Some<HashSet<String>>(temp_missing)
            return (false, missing_args)
        }

        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        return match (arguments.get(key)) {
            case Some<Any>(value) => value
            case None<Any> => None<Any>() // Note: Original spec suggests returning None type but Any can't be directly None
            // Alternative implementation that matches spec better:
            // match (arguments.get(key)) {
            //     case Some<T>(value) => value
            //     case None => return None<Any>() // Not ideal as we can't return None of Any directly
            // }
            // For a more correct version we'd need proper Option type support in return
            // Here using a sentinel value might be needed
        }
        // Fallback return (not ideal - better to redesign this method to return Option<Any>)
        return None<Any>() as Any // This is a workaround
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            this.required.add(arg)
        }
        this.types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        let typ = this.types.get(arg)
        return match (typ) {
            case Some<TypeInfo>(type_info) => {
                match (type_info) {
                    case TypeInfo.of<Int64>() => value.toInt64().getOrThrow()
                    case TypeInfo.of<Int32>() => value.toInt32().getOrThrow()
                    case TypeInfo.of<Bool>() => {
                        if (value.toLowerCase() == "true") { true } 
                        else if (value.toLowerCase() == "false") { false }
                        else { value } // fallback to string if can't convert
                    }
                    case TypeInfo.of<Float64>() => value.toFloat64().getOrThrow()
                    case _ => value // default to string if no special type
                }
            }
            case None<TypeInfo> => value // default to string if no type info
        }
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        if (n <= 1) {
            return 1
        }
        var result: Int64 = 1
        for (i in 2..(n + 1)) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let m_value = m ?? n
        if (m_value < 0 || m_value > n) {
            return 0
        }
        return factorial(n) / factorial(n - m_value)
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..(n + 1)) {
            total += factorial(n) / factorial(n - i)
        }
        return total
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let m_value = m ?? this.datas.size
        if (m_value < 0 || m_value > this.datas.size) {
            return ArrayList<ArrayList<Int64>>()
        }
        let result = ArrayList<ArrayList<Int64>>()
        select_permutations(ArrayList<Int64>(), this.datas, m_value, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..(this.datas.size + 1)) {
            let arrangements = ArrayList<ArrayList<Int64>>()
            let temp_result = ArrayList<ArrayList<Int64>>()
            select_permutations(ArrayList<Int64>(), this.datas, i, arrangements)
            for (j in 0..arrangements.size) {
                temp_result.add(arrangements[j])
            }
            for (j in 0..temp_result.size) {
                result.add(temp_result[j])
            }
        }
        return result
    }
}

