import std.collection.ArrayList

class AvgPartition {
    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        if (limit <= 0) {
            throw IllegalArgumentException("Limit must be greater than 0")
        }
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let size = lst.size
        let blockSize = size / limit
        let remainder = size % limit
        return (blockSize, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        let (blockSize, remainder) = setNum()
        let size = lst.size

        if (index < 0 || index >= limit) {
            throw IllegalArgumentException("Index out of bounds")
        }

        let start: Int64
        let end: Int64

        if (index < remainder) {
            start = index * (blockSize + 1)
            end = start + blockSize + 1
        } else {
            start = remainder * (blockSize + 1) + (index - remainder) * blockSize
            end = start + blockSize
        }

        // Handle case where index might go beyond list size (shouldn't happen due to earlier check)
        if (start >= size) {
            return ArrayList<Int64>([])
        }

        let endIndex = if (end > size) { size } else { end }
        let result = ArrayList<Int64>()
        for (i in start..<endIndex) {
            result.add(lst[i])
        }
        return result
    }
}

import std.collection.ArrayList

class BalancedBrackets {

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        var filtered_chars = ArrayList<String>()
        for (i in 0..expr.size) {
            let c = expr[i]
            let char_str = String(c)
            if (left_brackets.contains(char_str) || right_brackets.contains(char_str)) {
                filtered_chars.add(char_str)
            }
        }
        this.expr = ""
        for (i in 0..filtered_chars.size) {
            this.expr += filtered_chars[i]
        }
    }

    public func check_balanced_brackets(): Bool {
        this.stack.clear()
        var is_balanced = true

        for (i in 0..expr.size) {
            let c = expr[i]
            let char_str = String(c)

            if (left_brackets.contains(char_str)) {
                stack.add(char_str)
            } else if (right_brackets.contains(char_str)) {
                if (stack.size == 0) {
                    is_balanced = false
                    break
                }

                let top = stack.remove(at: stack.size - 1)
                let matching_left = match (char_str) {
                    case ")" => "("
                    case "}" => "{"
                    case "]" => "["
                    case _ => ""
                }

                if (top != matching_left) {
                    is_balanced = false
                    break
                }
            }
        }

        return is_balanced && stack.size == 0
    }
}

import std.error.*

class BankAccount {
    var balance: Int64

    public init(balance!: Int64 = 0) {
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        this.balance += amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance -= amount
        return this.balance
    }

    public func view_balance(): Int64 {
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance -= amount
        other_account.balance += amount
    }
}

