class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let digits1 = num1.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()
        let digits2 = num2.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()

        var result = ArrayList<Int64>()
        var carry: Int64 = 0
        let maxLen = if (digits1.size > digits2.size) { digits1.size } else { digits2.size }

        for (i in 0..maxLen) {
            let d1 = if (i < digits1.size) { digits1[i] } else { 0 }
            let d2 = if (i < digits2.size) { digits2[i] } else { 0 }
            let sum = d1 + d2 + carry
            result.add(sum % 10)
            carry = sum / 10
        }

        if (carry > 0) {
            result.add(carry)
        }

        let reversed = result.reversedArray()
        var str = ""
        for (i in 0..reversed.size) {
            str = str + String(reversed[i].toString())
        }
        return str
    }

    public static func subtract(num1: String, num2: String): String {
        let isNegative = compareStrings(num1, num2) < 0
        let (larger, smaller) = if (isNegative) { (num2, num1) } else { (num1, num2) }

        let digits1 = larger.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()
        let digits2 = smaller.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()

        var result = ArrayList<Int64>()
        var borrow: Int64 = 0

        for (i in 0..digits1.size) {
            let d1 = if (i < digits1.size) { digits1[i] } else { 0 }
            let d2 = if (i < digits2.size) { digits2[i] } else { 0 }
            var diff = d1 - d2 - borrow

            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(diff)
        }

        // Remove leading zeros
        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(at: result.size - 1)
        }

        let reversed = result.reversedArray()
        var str = ""
        for (i in 0..reversed.size) {
            str = str + String(reversed[i].toString())
        }

        return if (isNegative) { "-" + str } else { str }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let digits1 = num1.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()
        let digits2 = num2.toRuneArray().map({ r -> Int64 in 
            let v = r.toInt64() - 48
            return if (v >= 0 && v <= 9) { v } else { 0 } 
        }).reversedArray()

        var result = ArrayList<Int64>([0])

        for (i in 0..digits1.size) {
            var carry: Int64 = 0
            var temp = ArrayList<Int64>()

            for (j in 0..digits2.size) {
                let product = digits1[i] * digits2[j] + carry
                temp.add(product % 10)
                carry = product / 10
            }

            if (carry > 0) {
                temp.add(carry)
            }

            // Add to the result with proper shift
            for (k in 0..temp.size) {
                let pos = i + k
                if (pos < result.size) {
                    let sum = result[pos] + temp[k]
                    result[pos] = sum % 10
                    if (pos + 1 < result.size) {
                        result[pos + 1] += sum / 10
                    } else {
                        result.add(sum / 10)
                    }
                } else {
                    result.add(temp[k])
                }
            }
        }

        // Remove leading zeros
        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(at: result.size - 1)
        }

        let reversed = result.reversedArray()
        var str = ""
        for (i in 0..reversed.size) {
            str = str + String(reversed[i].toString())
        }
        return str
    }

    private static func compareStrings(a: String, b: String): Int64 {
        if (a.size != b.size) {
            return if (a.size > b.size) { 1 } else { -1 }
        }

        for (i in 0..a.size) {
            let ca = a[i].toInt64() - 48
            let cb = b[i].toInt64() - 48
            if (ca != cb) {
                return if (ca > cb) { 1 } else { -1 }
            }
        }
        return 0
    }
}

// Helper extension methods (if needed)
extension String {
    func reversedArray(): Array<Rune> {
        let runes = this.toRuneArray()
        var result = ArrayList<Rune>()
