class BinaryDataProcessor {
    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned_chars: ArrayList<Rune> = ArrayList<Rune>()
        for (c in this.binary_string.runes()) {
            match (c) {
                case r'0' => cleaned_chars.add(r'0')
                case r'1' => cleaned_chars.add(r'1')
                case _ => continue
            }
        }
        this.binary_string = String(cleaned_chars.toArray())
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let runes = this.binary_string.toRuneArray()
        let total_length = runes.size
        var zero_count = 0
        var one_count = 0

        for (i in 0..runes.size) {
            match (runes[i]) {
                case r'0' => zero_count += 1
                case r'1' => one_count += 1
                case _ => continue
            }
        }

        let zero_percent = Float64(zero_count) / Float64(total_length)
        let one_percent = Float64(one_count) / Float64(total_length)

        let result = HashMap<String, Float64>()
        result.add("Zeroes", zero_percent)
        result.add("Ones", one_percent)
        result.add("Bit length", Float64(total_length))
        return result
    }

    public func convert_to_ascii(): String {
        let runes = this.binary_string.toRuneArray()
        var ascii_bytes: ArrayList<UInt8> = ArrayList<UInt8>()

        for (i in 0..runes.size step 8) {
            let end = if (i + 8 < runes.size) { i + 8 } else { runes.size }
            let byte_str = String(runes.slice(i, end))
            if (byte_str.size == 8) {
                let byte = byte_str.toInt(2)?.getOrThrow() as? UInt8
                if (byte != null) {
                    ascii_bytes.add(byte)
                }
            }
        }

        // Convert bytes to string (simple ASCII interpretation)
        // Note: This is a simplified approach. A real implementation might need
        // proper UTF-8 validation and conversion.
        var result = ""
        for (byte in ascii_bytes) {
            // Simple ASCII character mapping (0-127)
            if (byte <= 127) {
                result += String.fromCharCode(byte)
            }
        }
        return result
    }

    public func convert_to_utf8(): String {
        // For UTF-8, we'll assume the binary string is properly formatted as UTF-8 bytes
        // This is a simplified approach - real UTF-8 handling is more complex
        return this.convert_to_ascii() // In practice, would need proper UTF-8 decoding
    }
}

