class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        /*
        Finds the rightmost occurrence of a character in the pattern.
        */
        var rightmost: Int64 = -1
        for (i in 0..<this.patLen:1) {
            if (this.pattern[i] == char[0]) { // Compare first Rune
                rightmost = i
            }
        }
        return rightmost
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        /*
        Determines the position of the first dismatch between the pattern and the text.
        */
        var i: Int64 = 0
        while (i < this.patLen) {
            let textRunes = this.text.toRuneArray()
            let patRunes = this.pattern.toRuneArray()
            if (currentPos + i >= this.textLen || textRunes[currentPos + i] != patRunes[i]) {
                return currentPos + i
            }
            i = i + 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        /*
        Implements the bad character heuristic of Boyer-Moore algorithm.
        */
        let badCharTable = HashMap<Rune, Int64>()
        let patRunes = this.pattern.toRuneArray()

        // Preprocess the pattern
        for (i in 0..<this.patLen:1) {
            badCharTable[patRunes[i]] = i // Store last occurrence index
        }

        let result = ArrayList<Int64>()
        var s: Int64 = 0 // s is shift of the pattern with respect to text

        while (s <= this.textLen - this.patLen) {
            let j: Int64 = this.patLen - 1
            var match = true

            // Keep reducing index j of pattern while characters of pattern and text match
            while (j >= 0 && this.pattern[j] == this.text[s + j]) {
                j = j - 1
            }

            // If the pattern is present at current shift, then increment count
            if (j < 0) {
                result.add(s)
                // Shift the pattern so that the next character in text aligns with the last occurrence of it in pattern
                let textRunes = this.text.toRuneArray()
                let char = textRunes[s + this.patLen]
                s = s + (if (badCharTable.contains(char)) { 
                    this.patLen - 1 - badCharTable[char]! 
                } else { 
                    this.patLen 
                })
            } else {
                // Shift the pattern so that the bad character in text aligns with the last occurrence of it in pattern
                let textRunes = this.text.toRuneArray()
                let char = textRunes[s + j]
                s = s + (if (badCharTable.contains(char)) { 
                    max(j - badCharTable[char]!, 1) 
                } else { 
                    j + 1 
                })
            }
        }
        return result
    }
}

