class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => 
            match (y) {
                case 0.0 => 1.0
                case _ => {
                    var result = 1.0
                    var base = x
                    var expo = y.toInt64()
                    if (expo < 0) {
                        base = 1.0 / base
                        expo = -expo
                    }
                    for (i in 0..expo) {
                        result = result * base
                    }
                    result
                }
            }
        })
    }

    public func calculate(expression: String): Option<Float64> {
        let tokens = expression.split(sep: [" ", ""], keepEmpty: false) // Simple split - actual implementation needs proper tokenization
        var operand_stack = ArrayList<Float64>()
        var operator_stack = ArrayList<String>()

        for (token in tokens) {
            match (token) {
                case r"\d+" => { // Simple number check - needs regex support
                    let num = token.toFloat64() ?? return None<Float64>()
                    operand_stack.add(num)
                }
                case ["+", "-", "*", "/", "^"] => {
                    while (operator_stack.size > 0 && precedence(operator_stack[operator_stack.size - 1]) >= precedence(token)) {
                        let (new_operands, new_operators) = apply_operator(operand_stack, operator_stack)
                        operand_stack = new_operands
                        operator_stack = new_operators
                    }
                    operator_stack.add(token)
                }
                case _ => return None<Float64>() // Invalid token
            }
        }

        while (operator_stack.size > 0) {
            let (new_operands, new_operators) = apply_operator(operand_stack, operator_stack)
            operand_stack = new_operands
            operator_stack = new_operators
        }

        return operand_stack.size == 1 ? Some<Float64>(operand_stack[0]) : None<Float64>()
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" | "-" => 1
            case "*" | "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if (operand_stack.size < 2 || operator_stack.size < 1) {
            return (operand_stack, operator_stack) // Invalid state - should retuen error in real implementation
        }

        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let b = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let a = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)

        let func_ = operators[op] ?? {x: Float64, y: Float64 => 0.0} // Safe fallback (shouldn't happen with proper init)
        var result = func_(a, b)
        operand_stack.add(result)

        return (operand_stack, operator_stack)
    }

    private func split(s: String, sep: Array<String>, keepEmpty: Bool): ArrayList<String> {
        // Simplified string splitting - real implementation would need proper logic
        let parts = ArrayList<String>()
        var current = ""
        for (c in s.toRuneArray()) {
            let char_str = String(c)
            if (sep.contains(char_str)) {
                if (keepEmpty || current != "") {
                    parts.add(current)
                }
                current = ""
            } else {
                current = current + char_str
            }
        }
        if (keepEmpty || current != "") {
            parts.add(current)
        }
        return parts
    }
}

