    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (i in 0..this.events.size) {
            if (this.events[i] == event) {
                this.events.remove(at: i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date == date) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if ((start_time >= event.start_time && start_time < event.end_time) ||
                (end_time > event.start_time && end_time <= event.end_time) ||
                (start_time <= event.start_time && end_time >= event.end_time)) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let sorted_events = ArrayList<Event>(this.events)
        let key = {e: Event => e.start_time.timestamp()}
        sort(sorted_events, key: key)

        let slots = ArrayList<(DateTime, DateTime)>()
        var last_end = date.of(hour: 0, minute: 0)

        for (event in sorted_events) {
            if (event.date == date && event.start_time > last_end) {
                slots.add((last_end, event.start_time))
            }
            last_end = max(last_end, event.end_time)
        }

        // Add slot after last event to next day
        let next_day = date.addDays(1)
        if (last_end < date.of(hour: 23, minute: 59)) {
            slots.add((last_end, date.of(hour: 23, minute: 59)))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let sorted_events = ArrayList<Event>(this.events)
        let key = {e: Event => e.start_time.timestamp()}
        sort(sorted_events, key: key)

        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        for (event in sorted_events) {
            if (event.start_time >= now) {
                upcoming.add(event)
                if (upcoming.size == num_events) {
                    break
                }
            }
        }

        return upcoming
    }
}

