    public init(n: Int64) {
        this.n = n
        this.primes = this.generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (this.n < 2) {
            return ArrayList<Int64>()
        }

        var is_prime = ArrayList<Bool>([true; size: (this.n + 1) as Int64])
        is_prime[0] = false
        is_prime[1] = false

        for (i in 2..this.n+1) {
            if (is_prime[i]) {
                for (j in i*i..this.n+1:step:i) {
                    is_prime[j] = false
                }
            }
        }

        var result = ArrayList<Int64>()
        for (i in 2..this.n+1) {
            if (is_prime[i]) {
                result.add(i)
            }
        }

        return result
    }

    public func get_primes(): ArrayList<Int64> {
        return this.primes
    }
}

