    func != (that: T): Bool
}

class Course <: Equatable<Course> {
    let name: String
    let start_time: String
    let end_time: String

    public init(name: String, start_time: String, end_time: String) {
        this.name = name
        this.start_time = start_time
        this.end_time = end_time
    }

    public override operator func != (that: Course): Bool {
        return this.name != that.name || this.start_time != that.start_time || this.end_time != that.end_time
    }

    public override operator func == (that: Course): Bool {
        return this.name == that.name && this.start_time == that.start_time && this.end_time == that.end_time
    }
}

class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!this.check_course_conflict(new_course: course)) {
            this.courses.add(course, at: this.courses.size)
        }
    }

    public func remove_course(course: Course): Unit {
        for (i in 0..this.courses.size) {
            if (this.courses[i] == course) {
                this.courses.remove(at: i)
                return
            }
        }
    }

    public func is_free_at(check_time: String): Bool {
        for (i in 0..this.courses.size) {
            let course = this.courses[i]
            if (check_time >= course.start_time && check_time <= course.end_time) {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        for (i in 0..this.courses.size) {
            let existing = this.courses[i]
            if (new_course.start_time < existing.end_time && 
                new_course.end_time > existing.start_time) {
                return true
            }
        }
        return false
    }
}

func main(): Unit {
    let classroom = Classroom(1)

    // Test add_course and check_course_conflict
    let math = Course(name: "math", start_time: "2023/09/01 08:00", end_time: "2023/09/01 09:40")
    classroom.add_course(course: math)

    // Test is_free_at
    println(classroom.is_free_at(check_time: "2023/09/01 10:00"))  // Should be true
    println(classroom.is_free_at(check_time: "2023/09/01 09:00"))  // Should be false

    // Test course conflict
    let se = Course(name: "SE", start_time: "2023/09/01 09:40", end_time: "2023/09/01 10:40")
    println(classroom.check_course_conflict(new_course: se))  // Should be true (boundary time included)

    // Test remove_course
    classroom.remove_course(course: math)
    println(classroom.is_free_at(check_time: "2023/09/01 09:00"))  // Should be true after removal
}

