class ClassRegistrationSystem {
    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"] ?? ""
        for (i in 0..this.students.size) {
            let s = this.students[i]
            if (s["name"] == name) {
                return 0
            }
        }
        this.students.add(student)
        if (!this.students_registration_classes.contains(name)) {
            this.students_registration_classes.add(name, ArrayList<String>())
        }
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (!this.students_registration_classes.contains(student_name)) {
            let classes = ArrayList<String>()
            this.students_registration_classes.add(student_name, classes)
        }
        let classes = this.students_registration_classes[student_name] ?? ArrayList<String>()
        classes.add(class_name)
        this.students_registration_classes[student_name] = classes
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for (i in 0..this.students.size) {
            let student = this.students[i]
            if (student["major"] == major) {
                result.add(student["name"] ?? "")
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for (i in 0..this.students.size) {
            let major = this.students[i]["major"] ?? ""
            majors.add(major)
        }
        let result = ArrayList<String>()
        for (major in majors) {
            result.add(major)
        }
        return result
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_counts = HashMap<String, Int64>()

        for (i in 0..this.students.size) {
            let student = this.students[i]
            if (student["major"] != major) {
                continue
            }
            let name = student["name"] ?? ""
            let classes = this.students_registration_classes[name]
            if (classes != null) {
                for (j in 0..classes.size) {
                    let class_name = classes[j]
                    let count = class_counts[class_name] ?? 0
                    class_counts[class_name] = count + 1
                }
            }
        }

        var max_count: Int64 = 0
        var popular_class: String = ""
        for (class_name in class_counts) {
            let count = class_counts[class_name] ?? 0
            if (count > max_count) {
                max_count = count
                popular_class = class_name
            }
        }

        return popular_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) {
            return 0
        }
        return factorial(n) / (factorial(m) * factorial(n - m))
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n + 1) {
            let c = count(n, i)
            // Check if adding c would overflow
            if (Int64.Max - total < c) {
                return Int64.Max
            }
            total += c
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let results = ArrayList<ArrayList<String>>()
        if (m <= 0 || m > this.datas.size) {
            return results
        }
        let temp = ArrayList<String>()
        this._select(0, temp, 0, m, results)
        return results
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let results = ArrayList<ArrayList<String>>()
        for (i in 1..this.datas.size + 1) {
            results.addAll(this.select(i))
        }
        return results
    }

    public func _select(dataIndex: Int64, 
                       resultList: ArrayList<String>, 
                       resultIndex: Int64, 
                       m: Int64, 
                       result: ArrayList<ArrayList<String>>): Unit {
        if (resultIndex == m) {
            let newCombination = ArrayList<String>(resultList)
            result.add(newCombination)
            return
        }

        for (i in dataIndex..this.datas.size) {
            resultList.add(this.datas[i])
            this._select(i + 1, resultList, resultIndex + 1, m, result)
            resultList.remove(at: resultIndex)
        }
    }

    // Helper overload for original _select method signature
    public func _select(dataIndex: Int64, 
                       resultList: ArrayList<String>, 
                       resultIndex: Int64, 
                       result: ArrayList<ArrayList<String>>): Unit {
        this._select(dataIndex, resultList, resultIndex, this.datas.size, result)
    }
}

