class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File.open(file_name, mode: "r")
        let content = file.readAll()
        let lines = content.split("\n")

        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        if lines.size > 0 {
            title = ArrayList<String>(lines[0].split(",").map({s: String => s.trim()}))
        }

        for (i in 1..lines.size) {
            if (i < lines.size) {
                let row = lines[i].split(",").map({s: String => s.trim()})
                if (row.size > 0) {
                    data.add(ArrayList<String>(row))
                }
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File.open(file_name, mode: "w")
            for (row in data) {
                let line = row.join(",")
                file.write(line + "\n")
            }
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)
        if (title.size == 0 || data.size == 0) {
            return 0
        }

        if (N < 0 || N >= title.size) {
            return 0
        }

        var new_title = ArrayList<String>()
        if (N < title.size) {
            new_title.add(title[N])
        }

        var new_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (N < row.size) {
                let cell = row[N]
                let new_cell = cell.toUpper()
                new_data.add(ArrayList<String>([new_cell]))
            }
        }

        let new_file_name = save_file_name.split(".").map({
            if (it == save_file_name.split(".").last) {
                "process." + it
            } else {
                it
            }
        }).join(".")

        // Alternative simpler way to add '_process' suffix
        let last_dot = save_file_name.lastIndexOf(".")
        let base_name = if (last_dot != -1) {
                            save_file_name.substring(0, last_dot)
                        } else {
                            save_file_name
                        }
        let extension = if (last_dot != -1) {
                           save_file_name.substring(last_dot)
                       } else {
                           ""
                       }
        let processed_file_name = base_name + "_process" + extension

        return this.write_csv(
            ArrayList<ArrayList<String>>([new_title].concat(new_data)),
            processed_file_name
        )
    }
}

