class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (num in data) {
            sum += num
        }
        let meanValue: Float64 = Float64(sum) / Float64(data.size)
        return round(meanValue * 100) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let size = data.size
        if (size == 0) {
            return 0.0
        }
        if (size % 2 == 1) {
            return Float64(sorted[size / 2])
        } else {
            let mid1: Float64 = Float64(sorted[size / 2 - 1])
            let mid2: Float64 = Float64(sorted[size / 2])
            let median: Float64 = (mid1 + mid2) / 2.0
            return round(median * 100) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequencyMap = HashMap<Int64, Int64>()
        for (num in data) {
            let count = frequencyMap.get(num) ?? 0
            frequencyMap.add(num, count + 1)
        }

        var maxCount: Int64 = 0
        for (num, count in frequencyMap) {
            if (count > maxCount) {
                maxCount = count
            }
        }

        let modes = ArrayList<Int64>()
        for (num, count in frequencyMap) {
            if (count == maxCount) {
                modes.add(num)
            }
        }

        // Sort the modes for consistent output (optional)
        sort(modes)
        return modes
    }
}

