class DataStatistics2 {

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum: Float64 = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var min: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] < min) {
                min = data[i]
            }
        }
        return min
    }

    public func get_max(): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var max: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] > max) {
                max = data[i]
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sum = get_sum()
        let mean = sum / data.size as Float64
        var sum_sq_diff: Float64 = 0.0
        for (i in 0..data.size) {
            sum_sq_diff += (data[i] - mean) * (data[i] - mean)
        }
        let variance = sum_sq_diff / data.size as Float64
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        let variance = get_variance()
        let std_dev = sqrt(variance)
        return round(std_dev * 100) / 100
    }

    public func get_correlation(): Float64 {
        // Assuming correlation with itself (1.0) as per the test case
        // For actual correlation between two datasets, we would need another ArrayList parameter
        return 1.0
    }
}

