class DataStatistics4 {

    public static func mean(data: ArrayList<Float64>): Float64 {
        var sum: Float64 = 0.0
        for (i in 0..<data.size) {
            sum += data[i]
        }
        return sum / data.size.toFloat64()
    }

    public static func variance(data: ArrayList<Float64>): Float64 {
        let m = mean(data: data)
        var sum: Float64 = 0.0
        for (i in 0..<data.size) {
            sum += (data[i] - m) * (data[i] - m)
        }
        return sum / data.size.toFloat64()
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if (data1.size != data2.size) {
            return 0.0
        }

        let m1 = mean(data: data1)
        let m2 = mean(data: data2)

        var cov: Float64 = 0.0
        var s1: Float64 = 0.0
        var s2: Float64 = 0.0

        for (i in 0..<data1.size) {
            let d1 = data1[i] - m1
            let d2 = data2[i] - m2
            cov += d1 * d2
            s1 += d1 * d1
            s2 += d2 * d2
        }

        let denominator = sqrt(s1) * sqrt(s2)
        if (denominator == 0.0) {
            return 0.0
        }
        return cov / denominator
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let m = mean(data: data)
        let v = variance(data: data)
        let std = sqrt(v)
        if (std == 0.0) {
            return 0.0
        }

        var sum: Float64 = 0.0
        for (i in 0..<data.size) {
            let dev = (data[i] - m) / std
            sum += dev * dev * dev
        }
        return sum / data.size.toFloat64()
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let m = mean(data: data)
        let v = variance(data: data)
        let std = sqrt(v)
        if (std == 0.0) {
            return 0.0
        }

        var sum: Float64 = 0.0
        for (i in 0..<data.size) {
            let dev = (data[i] - m) / std
            sum += dev * dev * dev * dev
        }
        return sum / data.size.toFloat64() - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let inv_sqrt_2pi = 1.0 / sqrt(2.0 * 3.141592653589793)

        for (i in 0..<data.size) {
            let exponent = -0.5 * ((data[i] - mu) / sigma) * ((data[i] - mu) / sigma)
            result.add(inv_sqrt_2pi * exp(exponent) / sigma)
        }

        return result
    }
}

