class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var plaintext: String = ""
        for (r in ciphertext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let shifted = (r - r'a' - shift % 26 + 26) % 26 + r'a'
                plaintext = plaintext + String.fromRune(shifted)
            } else if (r >= r'A' && r <= r'Z') {
                let shifted = (r - r'A' - shift % 26 + 26) % 26 + r'A'
                plaintext = plaintext + String.fromRune(shifted)
            } else {
                plaintext = plaintext + String.fromRune(r)
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        var plaintext: String = ""
        var keyIndex: Int64 = 0
        for (r in ciphertext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let keyRune = key.toRuneArray()[keyIndex % key.size].toLower()
                let shift = keyRune - r'a'
                let shifted = (r - r'a' - shift + 26) % 26 + r'a'
                plaintext = plaintext + String.fromRune(shifted)
                keyIndex = keyIndex + 1
            } else if (r >= r'A' && r <= r'Z') {
                let keyRune = key.toRuneArray()[keyIndex % key.size].toLower()
                let shift = keyRune - r'a'
                let shifted = (r - r'A' - shift + 26) % 26 + r'A'
                plaintext = plaintext + String.fromRune(shifted)
                keyIndex = keyIndex + 1
            } else {
                plaintext = plaintext + String.fromRune(r)
            }
        }
        return plaintext
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails == 1) {
            return encrypted_text
        }

        let length = encrypted_text.size
        let railIndices = ArrayList<ArrayList<Int64>>()
        for (i in 0..rails) {
            railIndices.add(ArrayList<Int64>())
        }

        var currentRail: Int64 = 0
        var direction: Int64 = 1
        for (i in 0..length) {
            railIndices[currentRail].add(i)
            currentRail = currentRail + direction
            if (currentRail == 0 || currentRail == rails - 1) {
                direction = -direction
            }
        }

        let charByRail = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            charByRail.add(ArrayList<Rune>())
        }

        var textIndex: Int64 = 0
        for (rail in 0..rails) {
            for (pos in railIndices[rail]) {
                if (textIndex < length) {
                    charByRail[rail].add(encrypted_text.toRuneArray()[pos])
                    textIndex = textIndex + 1
                }
            }
        }

        var result: String = ""
        var railPositions = ArrayList<Int64>()
        for (i in 0..rails) {
            railPositions.add(0)
        }

        var currentRail = 0
        direction = 1
        for (i in 0..length) {
            result = result + String.fromRune(charByRail[currentRail][railPositions[currentRail]])
            railPositions[currentRail] = railPositions[currentRail] + 1
            currentRail = currentRail + direction
            if (currentRail == 0 || currentRail == rails - 1) {
                direction = -direction
            }
        }

        return result
    }
}

