class Customer {
    let name: String
    let fidelity: Int64

    public init(name: String, fidelity: Int64) {
        this.name = name
        this.fidelity = fidelity
    }
}

class DiscountStrategy {
    let customer: Customer
    let cart: ArrayList<Product>
    let promotion: (DiscountStrategy) -> Float64

    public init(customer: Customer, cart: ArrayList<Product>, promotion!: (DiscountStrategy) -> Float64 = {_ => 0.0}) {
        this.customer = customer
        this.cart = cart
        this.promotion = promotion
    }

    public func total(): Float64 {
        var sum: Float64 = 0.0
        for (i in 0..cart.size) {
            let product = cart[i]
            sum += product.quantity * product.price
        }
        return sum
    }

    public func due(): Float64 {
        let total = this.total()
        let discount = this.promotion(this)
        return total - discount
    }

    public static func FidelityPromo(order: DiscountStrategy): Float64 {
        if (order.customer.fidelity > 1000) {
            return order.total() * 0.05
        }
        return 0.0
    }

    public static func BulkItemPromo(order: DiscountStrategy): Float64 {
        var discount: Float64 = 0.0
        for (i in 0..order.cart.size) {
            let product = order.cart[i]
            if (product.quantity >= 20) {
                discount += product.quantity * product.price * 0.10
            }
        }
        return discount
    }

    public static func LargeOrderPromo(order: DiscountStrategy): Float64 {
        if (order.cart.size >= 10) {
            return order.total() * 0.07
        }
        return 0.0
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.collection.HashSet

class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (0, 0) // Should never reach here for valid 8-puzzle
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        for (i in 0..3) {
            let row = ArrayList<Int64>()
            for (j in 0..3) {
                row.add(state[i][j])
            }
            new_state.add(row)
        }

        let (i, j) = this.find_blank(state: state)
        var new_i = i
        var new_j = j

        match (direction) {
            case "up" => if (i > 0) { new_i = i - 1 }
            case "down" => if (i < 2) { new_i = i + 1 }
            case "left" => if (j > 0) { new_j = j - 1 }
            case "right" => if (j < 2) { new_j = j + 1 }
            case _ => return new_state // Invalid direction
        }

        // Swap tiles
        let temp = new_state[i][j]
        new_state[i][j] = new_state[new_i][new_j]
        new_state[new_i][new_j] = temp

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = this.find_blank(state: state)
        let moves = ArrayList<String>()

        if (i > 0) {
            moves.add("up")
        }
        if (i < 2) {
            moves.add("down")
        }
        if (j > 0) {
            moves.add("left")
        }
        if (j < 2) {
            moves.add("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<ArrayList<ArrayList<Int64>>>()
        open_list.add(this.initial_state)

        let came_from = HashMap<ArrayList<ArrayList<Int64>>, (ArrayList<ArrayList<Int64>>, String)>()
        came_from.add(this.initial_state, (ArrayList<ArrayList<Int64>>(), "")) // Empty path for initial state

        while (open_list.size > 0) {
            let current_state = open_list[0]
            open_list.remove(at: 0)

            if (current_state == this.goal_state) {
                // Reconstruct path
                let path = ArrayList<String>()
                var state: Opt<ArrayList<ArrayList<Int64>>> = Some<ArrayList<ArrayList<Int64>>>(current_state)

                while (state != None<ArrayList<ArrayList<Int64>>>() && came_from.contains(key: state.getOrThrow())) {
                    let (prev_state, direction) = came_from[state.getOrThrow()]!
                    if (direction != "") {
                        path.add(0, direction) // Add at beginning to reverse path
                    }
                    state = Some<ArrayList<ArrayList<Int64>>>(prev_state)
                }

                return path
            }

            let possible_moves = this.get_possible_moves(state: current_state)
            for (move_dir in possible_moves) {
                let new_state = this.move(state: current_state, direction: move_dir)

                // Check if we've seen this state before
                var found = false
                for (existing_state in came_from.keys()) {
                    if (existing_state == new_state) {
                        found = true
                        break
                    }
                }

                if (!found) {
                    open_list.add(new_state)
                    came_from.add(new_state, (current_state, move_dir))
                }
            }
        }

        return ArrayList<String>() // No solution found
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap
import std.sort.*

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (recv.is_full_with_one_more_email(size)) {
            return false
        }
        let email = HashMap<String, Any>([
            ("sender", this.addr),
            ("receiver", recv.addr),
            ("content", content),
            ("size", size),
            ("time", DateTime.now().toString()),
            ("state", "unread")
        ])
        recv.inbox.add(email)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        for (i in 0..inbox.size) {
            let email = inbox[i]
            if (email["state"] == "unread") {
                let updatedEmail = HashMap<String, Any>(email)
                updatedEmail["state"] = "read"
                inbox[i] = updatedEmail
                return updatedEmail
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let currentSize = this.get_occupied_size()
        return currentSize + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var total: Int64 = 0
        for (i in 0..inbox.size) {
            let email = inbox[i]
            let size = email["size"] as? Int64 ?? 0
            total += size
        }
        return total
    }

    public func clear_inbox(size: Int64): Unit {
        let requiredSpace = this.capacity - size
        var currentSize = this.get_occupied_size()

        while (currentSize > requiredSpace && inbox.size > 0) {
            // Sort emails by time (oldest first)
            let emails = inbox.toArray()
            let lessThan = { l: HashMap<String, Any>, r: HashMap<String, Any> => 
                let lTime = l["time"] as? String ?? ""
                let rTime = r["time"] as? String ?? ""
                lTime < rTime
            }
            sort(emails, lessThan: lessThan)

            // Remove oldest email
            if (emails.size > 0) {
                let oldestEmail = emails[0]
                let oldestSize = oldestEmail["size"] as? Int64 ?? 0

                // Find and remove from inbox
                for (i in 0..inbox.size) {
                    let email = inbox[i]
                    let eTime = email["time"] as? String ?? ""
                    if (eTime == (oldestEmail["time"] as? String ?? "")) {
                        inbox.remove(at: i)
                        break
                    }
                }
                currentSize -= oldestSize
            }
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        let arr = plaintext.toRuneArray()
        for (i in 0..arr.size) {
            let c = arr[i]
            if (c >= r'a' && c <= r'z') {
                let shifted = (c - r'a' + shift % 26 + 26) % 26 + r'a'
                ciphertext += String.from(shifted)
            } else if (c >= r'A' && c <= r'Z') {
                let shifted = (c - r'A' + shift % 26 + 26) % 26 + r'A'
                ciphertext += String.from(shifted)
            } else {
                ciphertext += String.from(c)
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        var ciphertext = ""
        let key_runes = this.key.toRuneArray()
        let plain_runes = plain_text.toRuneArray()
        var key_index = 0

        for (i in 0..plain_runes.size) {
            let p = plain_runes[i]
            let k = key_runes[key_index % key_runes.size]
            key_index++

            if (p >= r'a' && p <= r'z') {
                let shift = (k - r'a')
                let ciphered = (p - r'a' + shift + 26) % 26 + r'a'
                ciphertext += String.from(ciphered)
            } else if (p >= r'A' && p <= r'Z') {
                let shift = (k - r'A')
                let ciphered = (p - r'A' + shift + 26) % 26 + r'A'
                ciphertext += String.from(ciphered)
            } else {
                ciphertext += String.from(p)
            }
        }
        return ciphertext
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let plain_runes = plain_text.toRuneArray()
        if (rails <= 1) {
            return plain_text
        }

        let table = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            table.add(ArrayList<Rune>())
        }

        var current_rail = 0
        var going_down = true

        for (i in 0..plain_runes.size) {
            table[current_rail].add(plain_runes[i])
            if (going_down) {
                current_rail++
                if (current_rail == rails - 1) {
                    going_down = false
                }
            } else {
                current_rail--
                if (current_rail == 0) {
                    going_down = true
                }
            }
        }

        var ciphertext = ""
        for (i in 0..rails) {
            for (j in 0..table[i].size) {
                ciphertext += String.from(table[i][j])
            }
        }
        return ciphertext
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.sort.*

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // Corresponds to operators: +, -, *, /, (, ), %, [placeholder]
    }

    public func calculate(expression: String): Float64 {
        prepare(expression: transform(expression: expression))
        var temp_stack: ArrayList<String> = ArrayList<String>()

        for (token in postfix_stack) {
            if (!ExpressionCalculator.is_operator(token)) {
                temp_stack.add(token)
            } else {
                let second_value = Decimal(temp_stack.remove(at: temp_stack.size - 1))!
                let first_value = Decimal(temp_stack.remove(at: temp_stack.size - 1))!
                let result = ExpressionCalculator._calculate(first_value, second_value, token)
                temp_stack.add(result.toString())
            }
        }

        let final_result = Decimal(temp_stack.get(0) ?? "0.0") ?? 0.0
        return final_result.toFloat64()
    }

    public func prepare(expression: String): Unit {
        let transformed = ExpressionCalculator.transform(expression: expression)
        var operator_stack: ArrayList<String> = ArrayList<String>()

        for (token in transformed.runesToArrayList()) {
            let token_str = token.toString()
            if (!ExpressionCalculator.is_operator(token_str)) {
                postfix_stack.add(token_str)
            } else if (token_str == "(") {
                operator_stack.add(token_str)
            } else if (token_str == ")") {
                while (operator_stack.get(operator_stack.size - 1) != "(") {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.remove(at: operator_stack.size - 1)
            } else {
                while (operator_stack.size > 0 && 
                       operator_stack.get(operator_stack.size - 1) != "(" && 
                       compare(token_str, operator_stack.get(operator_stack.size - 1)!)) {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.add(token_str)
            }
        }

        while (operator_stack.size > 0) {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        let op_to_index: HashMap<String, Int64> = HashMap<String, Int64>([
            ("+", 0),
            ("-", 1),
            ("*", 2),
            ("/", 3),
            ("(", 4),
            (")", 5),
            ("%", 6)
        ])

        let cur_idx = op_to_index.get(cur) ?? -1
        let peek_idx = op_to_index.get(peek) ?? -1

        if (peek == "(") {
            return false
        }
        return operat_priority[cur_idx] >= operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        switch (current_op) {
            case "+" => return first_value.add(second_value)
            case "-" => return first_value.subtract(second_value)
            case "*" => return first_value.multiply(second_value)
            case "/" => return first_value.divide(second_value)
            case "%" => return first_value.remainder(second_value)
            default   => return Decimal("0.0") ?? 0.0
        }
    }

    public static func transform(expression: String): String {
        var result = ""
        var space_flag = false

        for (r in expression.runes()) {
            let c = r.toString()
            if (c == " " && !space_flag) {
                continue
            } else if (c != " ") {
                if (ExpressionCalculator.is_operator(c) && (space_flag || result.runes().last().toString() == "")) {
                    // Handle cases where operators are adjacent without operands
                    // This simple version might not handle all edge cases perfectly
                    // In a real implementation, more robust parsing would be needed
                    result += c
                } else if (ExpressionCalculator.is_operator(c)) {
                    // Ensure proper spacing around operators (though input should be cleaned)
                    result += c
                } else {
                    result += c
                }
                space_flag = true
            }
        }

        // Remove all whitespace now
        var final_result = ""
        for (r in result.runes()) {
            let c = r.toString()
            if (c != " ") {
                final_result += c
            }
        }

        return final_result
    }
}

// Helper extension to convert string to ArrayList of characters (runes)
extension String {
    public func runesToArrayList(): ArrayList<String> {
        var result = ArrayList<String>()
        for (r in this.runes()) {
            result.add(r.toString())
        }
        return result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        let bmi = this.get_BMI()
        var standard: ArrayList<Int64>? = None

        for map in this.BMI_std {
            if map.contains("${this.sex}") {
                standard = map.get("${this.sex}")
                break
            }
        }

        if standard != None {
            let limits = standard.getOrThrow()
            if bmi < Float64(limits[0]) {
                return -1
            } else if bmi > Float64(limits[1]) {
                return 1
            } else {
                return 0
            }
        }
        return 0
    }

    public func calculate_calorie_intake(): Float64 {
        var bmr: Float64 = 0
        if this.sex == "male" {
            bmr = 10 * this.weight + 6.25 * this.height - 5 * Float64(this.age) + 5
        } else if this.sex == "female" {
            bmr = 10 * this.weight + 6.25 * this.height - 5 * Float64(this.age) - 161
        }

        let condition = this.condition_judge()
        switch (condition) {
            case 1 => return bmr * 1.2 // too fat
            case -1 => return bmr * 1.6 // too thin
            default => return bmr * 1.4 // normal
        }
    }
}

import std.collection.ArrayList
import std.sort.*

class GomokuGame {

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board_size || col < 0 || col >= board_size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        for (r in 0..board_size) {
            for (c in 0..board_size) {
                if (board[r][c] != " ") {
                    let directions = [
                        (0, 1),   // horizontal
                        (1, 0),   // vertical
                        (1, 1),   // diagonal
                        (1, -1)   // anti-diagonal
                    ]
                    for (dir in directions) {
                        if (_check_five_in_a_row(r, c, dir)) {
                            return Some<String>(board[r][c])
                        }
                    }
                }
            }
        }
        return None<String>()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let player = board[row][col]

        // Check positive direction
        var count = 1
        var r = row + dx
        var c = col + dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == player) {
            count += 1
            if (count >= 5) {
                return true
            }
            r += dx
            c += dy
        }

        // Check negative direction
        r = row - dx
        c = col - dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == player) {
            count += 1
            if (count >= 5) {
                return true
            }
            r -= dx
            c -= dy
        }

        return false
    }
}

func main() {
    let gomokuGame = GomokuGame(board_size: 10)
    let moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
    for (move in moves) {
        gomokuGame.make_move(move[0], move[1])
    }
    let winner = gomokuGame.check_winner()
    match (winner) {
        case Some<String>(w) => println("Winner: ${w}")
        case None<String>() => println("No winner yet")
    }
}

import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if (!available_rooms.contains(room_type)) {
            return "false"
        }

        let available = available_rooms.get(room_type) ?? 0
        if (room_number > available) {
            if (available == 0) {
                return "false"
            } else {
                return available.toString()
            }
        }

        // Update available rooms
        available_rooms.add(room_type, available - room_number)

        // Update booked rooms
        if (!booked_rooms.contains(room_type)) {
            booked_rooms.add(room_type, HashMap<String, Int64>())
        }

        let guest_rooms = booked_rooms.get(room_type) ?? HashMap<String, Int64>()
        if (guest_rooms.contains(name)) {
            let current = guest_rooms.get(name) ?? 0
            guest_rooms.add(name, current + room_number)
        } else {
            guest_rooms.add(name, room_number)
        }
        booked_rooms.add(room_type, guest_rooms)

        return "Success!"
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!booked_rooms.contains(room_type)) {
            return false
        }

        let guest_rooms = booked_rooms.get(room_type) ?? HashMap<String, Int64>()
        if (!guest_rooms.contains(name)) {
            return false
        }

        let booked = guest_rooms.get(name) ?? 0
        if (room_number > booked) {
            return false
        }

        // Update booked rooms
        if (room_number == booked) {
            guest_rooms.remove(name)
            if (guest_rooms.size == 0) {
                booked_rooms.remove(room_type)
            } else {
                booked_rooms.add(room_type, guest_rooms)
            }
        } else {
            guest_rooms.add(name, booked - room_number)
            booked_rooms.add(room_type, guest_rooms)
        }

        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if (available_rooms.contains(room_type)) {
            let current = available_rooms.get(room_type) ?? 0
            available_rooms.add(room_type, current + room_number)
        } else {
            available_rooms.add(room_type, room_number)
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        return available_rooms.get(room_type) ?? 0
    }
}

