interface Equatable<T> {
    func == (that: T): Bool
    func != (that: T): Bool
}

class Employee <: Equatable<Employee> {
    var name: String
    var position: String
    var department: String
    var salary: Int64

    public init(name: String, position: String, department: String, salary: Int64) {
        this.name = name
        this.position = position
        this.department = department
        this.salary = salary
    }

    public override operator func != (that: Employee): Bool {
        return this.name != that.name || 
               this.position != that.position || 
               this.department != that.department || 
               this.salary != that.salary
    }

    public override operator func == (that: Employee): Bool {
        return this.name == that.name && 
               this.position == that.position && 
               this.department == that.department && 
               this.salary == that.salary
    }
}

class HRManagementSystem {
    var employees: HashMap<Int64, Employee>

    public init() {
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        if (this.employees.contains(key: employee_id)) {
            return false
        } else {
            let employee = Employee(name: name, position: position, department: department, salary: salary)
            this.employees.add(key: employee_id, value: employee)
            return true
