import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        var result = ArrayList<Float64>()

        for (i in 0..<x_interp.size) {
            let xi = x_interp[i]
            var found = false

            // Find the interval containing xi
            for (j in 0..<x.size - 1) {
                if (x[j] <= xi && xi <= x[j + 1]) {
                    let slope = (y[j + 1] - y[j]) / (x[j + 1] - x[j])
                    let yi = y[j] + slope * (xi - x[j])
                    result.add(yi)
                    found = true
                    break
                }
            }

            // If xi is outside the range, use nearest endpoint
            if (!found) {
                if (xi <= x[0]) {
                    result.add(y[0])
                } else if (xi >= x[x.size - 1]) {
                    result.add(y[y.size - 1])
                }
            }
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        var result = ArrayList<Float64>()

        for (i in 0..<x_interp.size) {
            let xi = x_interp[i]
            for (j in 0..<y_interp.size) {
                let yj = y_interp[j]

                // Find the x interval
                var x_left = 0
                var x_right = x.size - 1
                for (k in 0..<x.size - 1) {
                    if (x[k] <= xi && xi <= x[k + 1]) {
                        x_left = k
                        x_right = k + 1
                        break
                    }
                }

                // Find the y interval
                var y_bottom = 0
                var y_top = y.size - 1
                for (l in 0..<y.size - 1) {
                    if (y[l] <= yj && yj <= y[l + 1]) {
                        y_bottom = l
                        y_top = l + 1
                        break
                    }
                }

                // Get the 4 corner points
                let q11 = z[x_left][y_bottom]
                let q21 = z[x_right][y_bottom]
                let q12 = z[x_left][y_top]
                let q22 = z[x_right][y_top]

                // Check if xi or yj is outside range
                if (x_left == x_right || y_bottom == y_top) {
                    // If either dimension is out of range, use nearest point
                    if (x_left == x_right && y_bottom == y_top) {
                        result.add(q11)
                    } else if (x_left == x_right) {
                        // Need to do 1D interpolation in y direction
                        let slope = (q12 - q11) / (y[y_top] - y[y_bottom])
                        let zi = q11 + slope * (yj - y[y_bottom])
                        result.add(zi)
                    } else {
                        // Need to do 1D interpolation in x direction
                        let slope = (q21 - q11) / (x[x_right] - x[x_left])
                        let zi = q11 + slope * (xi - x[x_left])
                        result.add(zi)
                    }
                } else {
                    // Standard bilinear interpolation
                    // Interpolate in x direction
                    let r1 = ((x[x_right] - xi) / (x[x_right] - x[x_left])) * q11 + ((xi - x[x_left]) / (x[x_right] - x[x_left])) * q21
                    let r2 = ((x[x_right] - xi) / (x[x_right] - x[x_left])) * q12 + ((xi - x[x_left]) / (x[x_right] - x[x_left])) * q22

                    // Interpolate in y direction
                    let zi = ((y[y_top] - yj) / (y[y_top] - y[y_bottom])) * r1 + ((yj - y[y_bottom]) / (y[y_top] - y[y_bottom])) * r2
                    result.add(zi)
                }
            }
        }

        // Flatten the result (since we process each x,y pair)
        // Note: The docstring example suggests we want a flat array for all combinations
        // This implementation matches the example behavior by processing all x_interp then y_interp
        // Alternative would be to return a 2D array, but docstring shows flat array
        return result
    }
}

import std.convert.Parsable
import std.convert.Formattable
