class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let octets = ip_address.split('.')
        if (octets.size != 4) {
            return false
        }

        for (i in 0..4) {
            let octet = octets[i]
            if (octet.size == 0) {
                return false
            }

            var num: Int64 = 0
            var valid = true
            for (j in 0..octet.size) {
                let c = octet[j]
                if (c < r'0' || c > r'9') {
                    valid = false
                    break
                }
                num = num * 10 + (c as! Int64 - r'0' as! Int64)
            }

            if (!valid || num < 0 || num > 255) {
                return false
            }
        }

        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) {
            return ArrayList<String>()
        }
        let octets = ip_address.split('.')
        let result = ArrayList<String>()
        for (i in 0..4) {
            result.add(octets[i])
        }
        return result
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let octets = ip_address.split('.')
        var binary_str = ""
        for (i in 0..4) {
            let num = octets[i].parseInt()!
            var binary = ""
            var n = num
            for (j in 0..8) {
                binary = (if (n & 128 != 0) "1" else "0") + binary
                n = n << 1
            }
            binary_str += binary
            if (i < 3) {
                binary_str += "."
            }
        }
        return binary_str
    }
}

