class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split('.')
        if parts.size != 4 {
            return false
        }

        for (part in parts) {
            if part.size == 0 || (part.size > 1 && part[0] == r'0') {
                return false
            }

            var num = 0
            for (c in part.runes()) {
                if c < r'0' || c > r'9' {
                    return false
                }
                num = num * 10 + (c - r'0').toInt64()
            }

            if num < 0 || num > 255 {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let parts = ip_address.split(':')
        if parts.size < 3 || parts.size > 8 {
            return false
        }

        let has_double_colon = ip_address.contains("::")
        if has_double_colon && (parts.size < 2 || parts.size > 7) {
            return false
        }

        for (part in parts) {
            if part.size == 0 {
                continue // handle :: compression
            }
            if part.size > 4 {
                return false
            }

            for (c in part.runes()) {
                if !((c >= r'0' && c <= r'9') || 
                     (c >= r'a' && c <= r'f') || 
                     (c >= r'A' && c <= r'F')) {
                    return false
                }
            }
        }
        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if !is_valid_ipv4(ip_address: ip_address) && !is_valid_ipv6(ip_address: ip_address) {
            return None<String>()
