class JobMarketplace {
    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title: job_title, company: company, requirements: requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        for (i in 0..<this.jobListings.size) {
            if (this.jobListings[i] == job) {
                this.jobListings.remove(at: i)
                break
            }
        }
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name: name, skills: skills, experience: experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        for (i in 0..<this.resumes.size) {
            if (this.resumes[i] == resume) {
                this.resumes.remove(at: i)
                break
            }
        }
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for (job in this.jobListings) {
            for (skill in job.requirements) {
                if (skill.contains(criteria)) {
                    result.add(job)
                    break
                }
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let applicants = ArrayList<Resume>()
        for (resume in this.resumes) {
            if (JobMarketplace.matches_requirements(resume: resume, requirements: job.requirements)) {
                applicants.add(resume)
            }
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        let resumeSkillsSet = HashSet<String>()
        for (skill in resume.skills) {
            resumeSkillsSet.add(skill)
        }

        for (req in requirements) {
            if (!resumeSkillsSet.contains(req)) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let N = testData.size
        var observed_agreement = 0.0
        var expected_agreement = 0.0

        // Calculate observed agreement
        for (i in 0..N) {
            let first = testData[i][0]
            var count = 0
            for (j in 0..k) {
                if (testData[i][j] == first) {
                    count += 1
                }
            }
            let prop = Float64(count) / Float64(k)
            observed_agreement += prop
        }
        observed_agreement = observed_agreement / Float64(N)

        // Calculate expected agreement
        let row_sums = ArrayList<Float64>(ArrayList<Float64>().withCapacity(Int32(N)))
        for (i in 0..N) {
            var sum = 0.0
            for (j in 0..k) {
                sum += Float64(testData[i][j])
            }
            row_sums.add(sum)
        }

        let col_props = ArrayList<Float64>(ArrayList<Float64>().withCapacity(Int32(k)))
        for (j in 0..k) {
            var col_sum = 0.0
            for (i in 0..N) {
                col_sum += Float64(testData[i][j])
            }
            col_props.add(col_sum / Float64(N * k))
        }

        for (i in 0..N) {
            var expected_row = 0.0
            let row_prop = Float64(row_sums[i]) / Float64(k)
            for (j in 0..k) {
                expected_row += col_props[j] * row_prop
            }
            expected_agreement += expected_row
        }
        expected_agreement = expected_agreement / Float64(N)

        return (observed_agreement - expected_agreement) / (1.0 - expected_agreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        let n_j = n
        var p_j = ArrayList<Float64>(ArrayList<Float64>().withCapacity(Int32(k)))

        // Calculate category proportions
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += Float64(testData[i][Int64(j)])
            }
            p_j.add(sum / Float64(N * n_j))
        }

        // Calculate P_o (observed agreement)
        var P_o = 0.0
        for (i in 0..N) {
            var sum_sq = 0.0
            for (j in 0..k) {
                sum_sq += Float64(testData[i][Int64(j)]) * Float64(testData[i][Int64(j)])
            }
            P_o += (Float64(sum_sq) - Float64(n_j)) / (Float64(n_j) * (Float64(n_j) - 1.0))
        }
        P_o = P_o / Float64(N)

        // Calculate P_e (expected agreement)
        var P_e = 0.0
        for (j in 0..k) {
            P_e += p_j[Int64(j)] * p_j[Int64(j)]
        }

        return (P_o - P_e) / (1.0 - P_e)
    }
}

import std.collection.ArrayList
