class LongestWord {
    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        // Remove punctuation using regex and split into words
        let cleaned = Regex.replace(r"[[:punct:]]", sentence, "")
        let words = cleaned.split(" ")

        var max_len = 0
        var result = ""

        for (word in words) {
            // Check if word exists in word_list
            if (this.word_list.contains(word)) {
                if (word.size > max_len) {
                    max_len = word.size
                    result = word
                }
            }
        }

        return result
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        let random = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let iconIndex = random.nextInt(ICONS.size)
                row.add(ICONS[iconIndex])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        // Check if positions are within bounds
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols || 
            x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) {
            return false
        }

        // Check if positions are the same
        if (x1 == x2 && y1 == y2) {
            return false
        }

        // Check if icons match
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }

        // Check if there's a path
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let visited = ArrayList<(Int64, Int64)>()
        return has_path_helper(x1, y1, x2, y2, visited)
    }

    private func has_path_helper(x1: Int64, y1: Int64, x2: Int64, y2: Int64, visited: ArrayList<(Int64, Int64)>): Bool {
        let pos = (x1, y1)

        // Check if out of bounds
        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1]) {
            return false
        }

        // Check if already visited
        if (MahjongConnect.contains(visited, pos)) {
            return false
        }
        visited.add(pos)

        // Base case: reached destination
        if (x1 == x2 && y1 == y2) {
            return true
        }

        // Check straight lines (horizontal/vertical)
        if ((x1 == x2 && (y1 + 1 == y2 || y1 - 1 == y2)) || 
            (y1 == y2 && (x1 + 1 == x2 || x1 - 1 == x2))) {
            return true
        }

        //Recursive checks for corner paths (up/down/left/right)
        return (has_path_helper(x1+1, y1, x2, y2, visited) && board[x1+1][y1] == " ") ||
               (has_path_helper(x1-1, y1, x2, y2, visited) && board[x1-1][y1] == " ") ||
               (has_path_helper(x1, y1+1, x2, y2, visited) && board[x1][y1+1] == " ") ||
               (has_path_helper(x1, y1-1, x2, y2, visited) && board[x1][y1-1] == " ")
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        for (i in 0..rows) {
            for (j in 0..cols) {
                if (board[i][j] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.collection.*

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        var left = center - diff - 1
        var right = center + diff + 1
        if (left < 0 || right >= string.runes().size) {
            return diff
        }
        if (string[left] == string[right]) {
            return palindromic_length(center: center, diff: diff + 1, string: string)
        } else {
            return diff
        }
    }

    public func palindromic_string(): String {
        if (this.input_string.runes().size == 0) {
            return ""
        }

        // Preprocess the string with separators
        var processed = Rune('|')
        for r in this.input_string.runes() {
            processed += r
            processed += Rune('|')
        }

        let processed_str = processed.toString()
        var max_len = 0
        var center = 0

        for i in 0..<processed_str.runes().size:1 {
            let current_len = palindromic_length(center: i, diff: 0, string: processed_str)
            if (current_len > max_len) {
                max_len = current_len
                center = i
            }
        }

        let start = (center - max_len) / 2
        let end = start + max_len
        var result_runes = ArrayList<Rune>()
        for i in 0..<max_len:1 {
            if ((center - max_len + i) % 2 == 0) {
                let original_pos = ((center - max_len + i) / 2)
                result_runes.add(this.input_string.runes()[original_pos])
            }
        }

        return result_runes.joinToString()
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0

        for (i in 0..predicted_labels.size) {
            let pred = predicted_labels[i]
            let true_val = true_labels[i]

            if (pred == 1 && true_val == 1) {
                this.true_positives += 1
            } else if (pred == 1 && true_val == 0) {
                this.false_positives += 1
            } else if (pred == 0 && true_val == 1) {
                this.false_negatives += 1
            } else if (pred == 0 && true_val == 0) {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_positives == 0) {
            return 0.0
        }
        return this.true_positives.toFloat64() / (this.true_positives + this.false_positives).toFloat64()
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_negatives == 0) {
            return 0.0
        }
        return this.true_positives.toFloat64() / (this.true_positives + this.false_negatives).toFloat64()
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        let prec = this.precision(predicted_labels, true_labels)
        let rec = this.recall(predicted_labels, true_labels)
        if (prec + rec == 0.0) {
            return 0.0
        }
        return 2.0 * prec * rec / (prec + rec)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let total = predicted_labels.size
        return (this.true_positives + this.true_negatives).toFloat64() / total.toFloat64()
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        func computeMRR(arr: ArrayList<Int64>, groundTruth: Int64): Float64 {
            var rank = 1.0
            var reciprocal = 0.0
            for (i in 0..<arr.size) {
                if arr[i] == 1 {
                    if i < groundTruth {
                        reciprocal = 1.0 / rank
                        break
                    } else {
                        rank += 1.0
                    }
                }
            }
            return reciprocal
        }

        let mrrList = ArrayList<Float64>()
        var sum = 0.0
        var count = 0

        match (data) {
            case let (tuple: ArrayList<Int64>, groundTruth: Int64) => {
                sum = computeMRR(arr: tuple, groundTruth: groundTruth)
                mrrList.add(sum)
            }
            case let list: ArrayList<(ArrayList<Int64>, Int64)> => {
                for (tuple in list) {
                    let (arr, groundTruth) = tuple
                    sum += computeMRR(arr: arr, groundTruth: groundTruth)
                    mrrList.add(computeMRR(arr: arr, groundTruth: groundTruth))
                }
                count = list.size
            }
            case _ => {
                return (0.0, mrrList)
            }
        }

        if count == 0 {
            return (0.0, mrrList)
        } else {
            return (sum / Float64(count), mrrList)
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        func computeAP(arr: ArrayList<Int64>, groundTruth: Int64): Float64 {
            var relevant = 0
            var precisionSum = 0.0
            var correctAtK = 0

            for (k in 0..<arr.size) {
                if arr[k] == 1 {
                    relevant += 1
                    correctAtK += 1
                    let precisionAtK = Float64(correctAtK) / Float64(k + 1)
                    if relevant <= groundTruth {
                        precisionSum += precisionAtK
                    }
                }
            }

            let minRelevant = min(relevant, groundTruth)
            if minRelevant == 0 {
                return 0.0
            }
            return precisionSum / Float64(minRelevant)
        }

        let mapList = ArrayList<Float64>()
        var sum = 0.0
        var count = 0

        match (data) {
            case let (tuple: ArrayList<Int64>, groundTruth: Int64) => {
                sum = computeAP(arr: tuple, groundTruth: groundTruth)
                mapList.add(sum)
            }
            case let list: ArrayList<(ArrayList<Int64>, Int64)> => {
                for (tuple in list) {
                    let (arr, groundTruth) = tuple
                    let ap = computeAP(arr: arr, groundTruth: groundTruth)
                    sum += ap
                    mapList.add(ap)
                }
                count = list.size
            }
            case _ => {
                return (0.0, mapList)
            }
        }

        if count == 0 {
            return (0.0, mapList)
        } else {
            return (sum / Float64(count), mapList)
        }
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var mine_map = ArrayList<ArrayList<String>>()
        var mines_placed = 0
        var random = Random()

        // Initialize empty map
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            mine_map.add(row)
        }

        // Place mines
        while (mines_placed < k) {
            let x = random.nextInt(0, n)
            let y = random.nextInt(0, n)
            if (mine_map[x][y] != "X") {
                mine_map[x] = mine_map[x].copy()
                mine_map[x][y] = "X"
                mines_placed += 1

                // Update surrounding cells
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        if (dx == 0 && dy == 0) continue
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && mine_map[nx][ny] != "X") {
                            let current = mine_map[nx].copy()
                            let count = if (current[ny] == "-") {
                                0
                            } else {
                                parse<Int64>(current[ny])!
                            }
                            mine_map[nx] = current
                            mine_map[nx][ny] = (count + 1).toString()
                        }
                    }
                }
            }
        }

        // Reset to proper mine display (last pass overrides numbers)
        var final_map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                if (mine_map[i][j] == "X") {
                    row.add("X")
                } else {
                    let count = parse<Int64>(mine_map[i][j])!
                    row.add(count.toString())
                }
            }
            final_map.add(row)
        }

        return final_map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (map[i][j] == "-" && this.minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= this.n || y < 0 || y >= this.n) {
            return this.player_map
        }

        if (this.player_map[x][y] != "-") {
            return this.player_map
        }

        if (this.minesweeper_map[x][y] == "X") {
            this.player_map[x] = this.player_map[x].copy()
            this.player_map[x][y] = "X"
            return false // Game over
        }

        let value = this.minesweeper_map[x][y]
        this.player_map[x] = this.player_map[x].copy()
        this.player_map[x][y] = value

        // If all non-mine cells are revealed
        if (this.check_won(this.player_map)) {
            return true // Player won
        }

        return this.player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.time.parse
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seat_rows = ArrayList<ArrayList<Int64>>()
        for (i in 0..n:1) {
            let row = ArrayList<Int64>()
            for (j in 0..n:1) {
                row.add(0)
            }
            seat_rows.add(row)
        }

        let movie = HashMap<String, Any>()
        movie.add("name", name)
        movie.add("price", price)
        movie.add("start_time", DateTime.parse(start_time, "yyyy/MM/dd HH:mm"))
        movie.add("end_time", DateTime.parse(end_time, "yyyy/MM/dd HH:mm"))
        movie.add("seats", seat_rows)

        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            let movie_name = movie["name"] ?? None<String>()
            if movie_name is None {
                continue
            }
            let name_value = (movie_name as Some<String>).value
            if (name_value == name) {
                let seats = movie["seats"] ?? None<ArrayList<ArrayList<Int64>>>()
                if seats is None {
                    return "Booking failed."
                }
                let seats_value = (seats as Some<ArrayList<ArrayList<Int64>>>).value

                for (seat in seats_to_book) {
                    let row = seat[0] ?? None<Int64>()
                    let col = seat[1] ?? None<Int64>()
                    if (row is None) || (col is None) {
                        return "Booking failed."
                    }
                    let row_idx = (row as Some<Int64>).value
                    let col_idx = (col as Some<Int64>).value
                    if (row_idx < 0) || (col_idx < 0) || (row_idx >= seats_value.size) || (col_idx >= seats_value[row_idx].size) {
                        return "Booking failed."
                    }
                    if seats_value[row_idx][col_idx] != 0 {
                        return "Booking failed."
                    }
                }

                for (seat in seats_to_book) {
                    let row = seat[0] ?? None<Int64>()
                    let col = seat[1] ?? None<Int64>()
                    let row_idx = (row as Some<Int64>).value
                    let col_idx = (col as Some<Int64>).value
                    seats_value[row_idx][col_idx] = 1
                }

                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        let result = ArrayList<String>()

        for (movie in movies) {
            let movie_start = movie["start_time"] ?? None<DateTime>()
            let movie_end = movie["end_time"] ?? None<DateTime>()
            if (movie_start is Some<DateTime>) && (movie_end is Some<DateTime>) {
                let movie_start_value = (movie_start as Some<DateTime>).value
                let movie_end_value = (movie_end as Some<DateTime>).value

                if movie_start_value < end && movie_end_value > start {
                    let movie_name = movie["name"] ?? None<String>()
                    if movie_name is Some<String> {
                        let movie_name_value = (movie_name as Some<String>).value
                        result.add(movie_name_value)
                    }
                }
            }
        }

        return result
    }
}

import std.collection.ArrayList
import std.random.Random

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        if (this.playlist.contains(song)) {
            let index = this.playlist.indexOf(song)
            if (index != -1) {
                this.playlist.remove(at: index)
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song == None && this.playlist.size > 0) {
            this.current_song = Some(this.playlist[0])
            return this.current_song
        }
        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }
        let current_index = this.playlist.indexOf(this.current_song ?? "")
        if (current_index == -1 || current_index + 1 >= this.playlist.size) {
            return false
        }
        this.current_song = Some(this.playlist[current_index + 1])
        return true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }
        let current_index = this.playlist.indexOf(this.current_song ?? "")
        if (current_index == -1 || current_index - 1 < 0) {
            return false
        }
        this.current_song = Some(this.playlist[current_index - 1])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let random = Random()
        let shuffled: ArrayList<String> = ArrayList<String>()
        while (this.playlist.size > 0) {
            let index = random.nextInt(this.playlist.size)
            shuffled.add(this.playlist[index])
            this.playlist.remove(at: index)
        }
        while (shuffled.size > 0) {
            let index = random.nextInt(shuffled.size)
            this.playlist.add(shuffled[index])
            shuffled.remove(at: index)
        }
        return true
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        let stop_words = ArrayList<String>(["a", "an", "the"])
        return stop_words
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var result = ArrayList<ArrayList<String>>()
        for (text in string_list) {
            let words = text.split(" ")
            var filtered_words = ArrayList<String>()
            for (word in words) {
                var should_remove = false
                for (stop_word in stop_word_list) {
                    if (word == stop_word) {
                        should_remove = true
                        break
                    }
                }
                if (!should_remove) {
                    filtered_words.add(word)
                }
            }
            result.add(filtered_words)
        }
        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_word_list = this.construct_stop_word_list()
        return this.remove_stop_words(string_list: string_list, stop_word_list: stop_word_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        let english_letters_and_spaces = Regex("[a-zA-Z ]+")

        for (i in 0..string_list.size) {
            let str = string_list[i]
            // Keep only English letters and spaces
            let match = english_letters_and_spaces.find(str)
            let filtered = if (match != None<Regex.Match>()) { 
                match.getOrThrow().group(0) 
            } else { 
                "" 
            }
            // Convert to lowercase and split into words
            let lower = filtered.toLowerCase()
            let words = ArrayList<String>()
            var current_word = ""

            for (j in 0..lower.size) {
                let c = lower[j]
                if (c == r' ') {
                    if (current_word != "") {
                        words.add(current_word)
                        current_word = ""
                    }
                } else {
                    current_word = current_word + c.toString()
                }
            }
            if (current_word != "") {
                words.add(current_word)
            }

            words_list.add(words)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq_map = HashMap<String, Int64>()

        for (i in 0..words_list.size) {
            let words = words_list[i]
            for (j in 0..words.size) {
                let word = words[j]
                freq_map[word] = (freq_map[word] ?? 0) + 1
            }
        }

        // Convert to list of entries for sorting
        var entries = ArrayList< (String, Int64) >()
        for (entry in freq_map) {
            entries.add((entry.key, entry.value))
        }

        // Sort by frequency descending
        let lessThan = { l: (String, Int64), r: (String, Int64) => l[1] < r[1] }
        sort(entries, lessThan: lessThan, descending: true)

        // Convert back to HashMap (only keeping top 5)
        var result = HashMap<String, Int64>()
        let limit = if (entries.size > 5) 5 else entries.size
        for (i in 0..limit) {
            if (i < entries.size) {
                let (word, count) = entries[i]
                result[word] = count
            }
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

