import std.convert.Parsable
import std.unicode.UnicodeStringExtension
import std.collection.*

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                           "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x == None<String>()) {
            return "INVALID INPUT"
        }
        let str = x.getOrThrow()
        return this.format_string(str)
    }

    public func format_string(x: String): String {
        var filtered = ""
        for (c in x.runes()) {
            if (c >= r'0' && c <= r'9') {
                filtered = "${filtered}${String.fromRune(c)}"
            }
        }

        if (filtered.size == 0) {
            return "INVALID INPUT"
        }

        var result = ""
        let length = filtered.size as Int64

        for (i in (0..(length / 3)) : -1) {
            let start = i * 3
            let end = start + 3 min length
            if (start >= length) {
                continue
            }
            let chunk = filtered[start..end]
            let chunkInt = chunk.toInt64() ?? 0
            if (chunkInt == 0 && i == 0 && result.size == 0) {
                continue // Skip leading zeros
            }

            var chunkStr = ""
            if (chunkInt >= 100) {
                let hundred = (chunkInt / 100) as Int64
                chunkStr = "${this.NUMBER[hundred]} HUNDRED"
                let remainder = chunkInt % 100
                if (remainder > 0) {
                    chunkStr = "${chunkStr} AND ${this.trans_two(String(remainder))}"
                }
            } else {
                chunkStr = this.trans_two(chunk)
            }

            if (chunkStr.size > 0) {
                if (result.size > 0) {
                    let more = this.parse_more(i)
                    if (more.size > 0) {
                        chunkStr = "${chunkStr} ${more}"
                    }
                }
                result = "${chunkStr} ${result}".trim()
            } else if (i == 0 && result.size == 0) {
                result = "ZERO"
            }
        }

        return "${result} ONLY".trim()
    }

    public func trans_two(s: String): String {
        if (s.size == 1) {
            let num = s.toInt64() ?? 0
            return this.NUMBER[num]
        }

        let num = s.toInt64() ?? 0
        if (num >= 10 && num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else if (num >= 20 && num < 100) {
            let ten = (num / 10) as Int64
            let one = (num % 10) as Int64
            let tenStr = this.NUMBER_TEN[ten - 1]
            let oneStr = if (one > 0) { " ${this.NUMBER[one]}" } else { "" }
            return "${tenStr}${oneStr}"
        } else if (num == 0) {
            return ""
        } else {
            return this.NUMBER[num]
        }
    }

    public func trans_three(s: String): String {
        let num = s.toInt64() ?? 0
        let hundred = (num / 100) as Int64
        let remainder = num % 100

        if (hundred > 0 && remainder > 0) {
            return "${this.NUMBER[hundred]} HUNDRED AND ${this.trans_two(String(remainder))}"
        } else if (hundred > 0) {
            return "${this.NUMBER[hundred]} HUNDRED"
        } else {
            return this.trans_two(String(remainder))
        }
    }

    public func parse_more(i: Int64): String {
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

func main() {
    let formatter = NumberWordFormatter()
    println(formatter.format(Some<String>("123456")))  // ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY
    println(formatter.format_string("23"))          // TWENTY THREE ONLY
    println(formatter.format_string("123"))         // ONE HUNDRED AND TWENTY THREE ONLY
    println(formatter.trans_two("23"))              // TWENTY THREE
    println(formatter.trans_three("123"))           // ONE HUNDRED AND TWENTY THREE
    println(formatter.parse_more(1))                // THOUSAND
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        var result = String("")
        var i = 0
        while (i < string.size) {
            if (string[i] == r'&' && i + 2 < string.size && string[i+1] == r'#') {
                var j = i + 2
                var is_hex = false
                if (j < string.size && string[j] == r'x') {
                    is_hex = true
                    j += 1
                }

                var num_str = String("")
                while (j < string.size && string[j] != r';') {
                    num_str += string[j].toString()
                    j += 1
                }

                if (j < string.size && string[j] == r';') {
                    let num = if (is_hex) {
                        num_str.toInt64(radix: 16) ?? 0
                    } else {
                        num_str.toInt64() ?? 0
                    }
                    result += num.toRune().toString()
                    i = j + 1
                    continue
                }
            }
            result += string[i].toString()
            i += 1
        }
        return result
    }

    public static func is_hex_char(char: Rune): Bool {
        return match (char) {
            case r'0'..r'9' => true
            case r'a'..r'f' => true
            case r'A'..r'F' => true
            case _ => false
        }
    }
}

