    }

    public override operator func == (that: SearchInfo): Bool {
        return this.keyword == that.keyword && this.total_results == that.total_results && this.total_pages == that.total_pages && this.results == that.results
    }
}

class PageUtil {

    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        if (page_number < 1 || page_number > this.total_pages) {
            return ArrayList<Int64>()
        }
        let start = (page_number - 1) * this.page_size
        let end = start + this.page_size
        let result = ArrayList<Int64>()
        for (i in start..end) {
            if (i < this.data.size) {
                result.add(this.data[i])
            }
        }
        return result
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if (page_number < 1 || page_number > this.total_pages) {
            return None<PageInfo>
        }
        let start = (page_number - 1) * this.page_size
        let end = start + this.page_size
        let page_data = ArrayList<Int64>()
        for (i in start..end) {
            if (i < this.data.size) {
                page_data.add(this.data[i])
            }
        }
        let has_previous = page_number > 1
        let has_next = page_number < this.total_pages
        return Some<PageInfo>(PageInfo(
            current_page: page_number,
            per_page: this.page_size,
            total_pages: this.total_pages,
            total_items: this.total_items,
            has_previous: has_previous,
            has_next: has_next,
            data: page_data
        ))
    }

    public func search(keyword: String): SearchInfo {
        let results = ArrayList<Int64>()
        var total_results = 0
        // Simple numeric search (assuming keyword is a string representation of number)
        for (i in 0..this.data.size) {
            let num_str = "${this.data[i]}"
            if (num_str.contains(keyword)) {
                results.add(this.data[i])
                total_results += 1
            }
        }
        let total_pages = (total_results + this.page_size - 1) / this.page_size
        return SearchInfo(
            keyword: keyword,
            total_results: total_results,
            total_pages: total_pages,
            results: results
        )
    }
}

class PersonRequest {
    let name: Option<String>
    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        this.name = PersonRequest._validate_name(name) 
        this.sex = PersonRequest._validate_sex(sex)
        this.phoneNumber = PersonRequest._validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        if (name.size == 0 || name.size > 33) {
            return None<String>
        } else {
            return Some<String>(name)
        }
    }

    public static func _validate_sex(sex: String): Option<String> {
        match (sex) {
            case "Man" => Some<String>(sex)
            case "Woman" => Some<String>(sex)
            case "UGM" => Some<String>(sex)
            case _ => None<String>
        }
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        if (phoneNumber.size != 11 || !phoneNumber.all { c => c >= '0' && c <= '9' }) {
            return None<String>
        } else {
            return Some<String>(phoneNumber)
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (row in 0..map.size) {
                for (col in 0..map[row].size) {
                    let cell = map[row][col]
                    match (cell) {
                        case "O" => {
                            this.player_row = row
                            this.player_col = col
                        }
                        case "G" => {
                            this.targets.add(ArrayList<Int64>([row, col]))
                            this.target_count += 1
                        }
                        case "X" => {
                            this.boxes.add(ArrayList<Int64>([row, col]))
                        }
                        case _ => {} // do nothing
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_on_target = 0
        for (box in boxes) {
            var on_target = false
            for (target in targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    on_target = true
                    break
                }
            }
            if (on_target) {
                box_on_target += 1
            }
        }
        this.is_game_over = box_on_target == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr = match (direction) {
            case "w" => -1
            case "s" => 1
            case _ => 0
        }
        let dc = match (direction) {
            case "a" => -1
            case "d" => 1
            case _ => 0
        }

        // Skip if invalid direction
        if (dr == 0 && dc == 0) {
            return this.check_win()
        }

        let new_row = this.player_row + dr
        let new_col = this.player_col + dc

        // Check wall collision
        if (new_row < 0 || new_row >= this.map.size || 
            new_col < 0 || new_col >= this.map[0].size || 
            this.map[new_row][new_col] == "#") {
            return this.check_win()
        }

        // Check box push
        var box_index = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == new_row && this.boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            let box_new_row = new_row + dr
            let box_new_col = new_col + dc

            // Check if box would hit wall or another box
            if (box_new_row < 0 || box_new_row >= this.map.size ||
                box_new_col < 0 || box_new_col >= this.map[0].size ||
                this.map[box_new_row][box_new_col] == "#") {
                return this.check_win()
            }

            // Check if another box is in the way
            var another_box = false
            for (box in this.boxes) {
                if (box[0] == box_new_row && box[1] == box_new_col) {
                    another_box = true
                    break
                }
            }
            if (another_box) {
                return this.check_win()
            }

            // Move the box
            this.boxes[box_index][0] = box_new_row
            this.boxes[box_index][1] = box_new_col
        }

        // Move the player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }

    // Helper method for testing (not part of the original question)
    public func print_map(): Unit {
        for (row in 0..this.map.size) {
            for (col in 0..this.map[row].size) {
                var is_player = false
                var is_box = false
                if (this.player_row == row && this.player_col == col) {
                    print("O ")
                    is_player = true
                }
                for (box in this.boxes) {
                    if (box[0] == row && box[1] == col) {
                        print("X ")
                        is_box = true
                        break
                    }
                }
                if (!is_player && !is_box) {
                    print(this.map[row][col] + " ")
                }
            }
            println("")
        }
    }
}

import std.regex.Regex
import std.collection.ArrayList
import std.sort.*

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex(pattern: pattern)
        return regex.matches(text) != None<Match>()
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern: pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (m in matches) {
            result.add(m.value)
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern: pattern)
        let splitted = regex.split(text)
        let result = ArrayList<String>()
        for (s in splitted) {
            result.add(s)
        }
        return result
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex(pattern: pattern)
        return regex.replace(text, replacement: replacement)
    }

    public func generate_email_pattern(): String {
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = this.generate_split_sentences_pattern()
        let regex = Regex(pattern: pattern)
        let parts = regex.split(text)
        let result = ArrayList<String>()
        for (i in 0..parts.size:1) {
            let part = parts[i].trim()
            if (i == parts.size - 1 && parts.size > 1) {
                // Handle last part which might contain punctuation
                let lastPart = parts[parts.size - 1]
                let lastIndex = text.lastIndexOf(lastPart)
                if (lastIndex != None<Int64>()) {
                    let start = lastIndex.getOrThrow()
                    result.add(text[start..])
                }
            } else if (i < parts.size - 1) {
                let nextPartStart = text.indexOf(parts[i+1])
                if (nextPartStart != None<Int64>()) {
                    let start = text.indexOf(parts[i])
                    let end = nextPartStart.getOrThrow()
                    let matchPattern = #'[.!?]$'#
                    let matchRegex = Regex(pattern: matchPattern)
                    let lastChar = parts[i].substring(parts[i].size - 1)
                    if (matchRegex.matches(lastChar) != None<Match>()) {
                        result.add(parts[i])
                    } else {
                        let splitPos = text.lastIndexOf(parts[i]) + parts[i].size - 1
                        let precedingText = text[0..splitPos]
                        let lastPunctuationPos = precedingText.lastIndexOf(r'.') ?? 
                                                 precedingText.lastIndexOf(r'!') ?? 
                                                 precedingText.lastIndexOf(r'?')
                        if (lastPunctuationPos != None<Int64>()) {
                            result.add(text[0..lastPunctuationPos.getOrThrow()+1].trim())
                        }
                    }
                }
            }
        }
        // Simplified implementation (actual logic might need adjustment based on exact requirements)
        // Alternative simpler approach:
        let simplerResult = ArrayList<String>()
        let sentences = text.split(r'[.!?] ')
        for (s in sentences) {
            if (s.size > 0) {
                simplerResult.add(s.trim())
            }
        }
        return simplerResult
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = this.generate_phone_number_pattern()
        let regex = Regex(pattern: pattern)
        return regex.matches(phone_number) != None<Match>()
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = this.generate_email_pattern()
        let regex = Regex(pattern: pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (m in matches) {
            result.add(m.value)
        }
        return result
    }
}

class RPGCharacter {
    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = max(0, this.attack_power - other_character.defense)
        other_character.hp = max(0, other_character.hp - damage)
    }

    public func heal(): Int64 {
        let heal_amount = min(10, 100 - this.hp)
        this.hp = min(100, this.hp + heal_amount)
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        while amount > 0 && this.level < 100 {
            let required_exp = 100 * this.level
            let exp_to_add = min(amount, required_exp - this.exp)
            this.exp += exp_to_add
            amount -= exp_to_add

            if this.exp >= 100 * this.level {
                this.level_up()
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if this.level >= 100 {
            return (this.level, this.hp, this.attack_power, this.defense)
        }

        this.exp = 0
        this.level += 1
        this.hp = min(100, this.hp + 20)
        this.attack_power += 5
        this.defense += 5

        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {
    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        let exists = white_list.any({ it == addr })
        if (exists) {
            return None<ArrayList<Int64>>()
        }
        var new_list = ArrayList<Int64>(white_list)
        new_list.add(addr)
        this.white_list = new_list
        return Some<ArrayList<Int64>>(new_list)
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        let index = white_list.indexOf({ it == addr })
        match (index) {
            case None<Int>() => return None<ArrayList<Int64>>()
            case Some<Int>(i) => {
                var new_list = ArrayList<Int64>(white_list)
                new_list.remove(at: i)
                this.white_list = new_list
                return Some<ArrayList<Int64>>(new_list)
            }
        }
    }

    public func recv(info: HashMap<String, Any>): Any {
        let addr_opt = info.get("addr")
        match (addr_opt) {
            case None<Any>() => return None<Any>()
            case Some<Any>(addr_any) => {
                match (addr_any) {
                    case r: Int64 => {
                        if (white_list.contains(r)) {
                            let content_opt = info.get("content")
                            match (content_opt) {
                                case None<Any>() => return None<Any>()
                                case Some<Any>(content) => {
                                    // Store the received info
                                    this.receive_struct = HashMap<String, Any>([
                                        ("addr", r),
                                        ("content", content)
                                    ])
                                    return content
                                }
                            }
                        } else {
                            return None<Any>()
                        }
                    }
                    case _ => return None<Any>()
                }
            }
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        let addr_opt = info.get("addr")
        match (addr_opt) {
            case None<Any>() => return Some<String>("info structure is not correct")
            case Some<Any>(addr_any) => {
                match (addr_any) {
                    case r: Int64 => {
                        let content_opt = info.get("content")
                        match (content_opt) {
                            case None<Any>() => return Some<String>("info structure is not correct")
                            case Some<Any>(content) => {
                                // Store the sent info
                                this.send_struct = HashMap<String, Any>([
                                    ("addr", r),
                                    ("content", content)
                                ])
                                return None<String>()
                            }
                        }
                    }
                    case _ => return Some<String>("info structure is not correct")
                }
            }
        }
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        match (type_struct) {
            case "send" => {
                // Make a copy to avoid external modification
                let copy = HashMap<String, Any>()
                for (k, v) in send_struct {
                    copy.add(k, v)
                }
                return Some<HashMap<String, Any>>(copy)
            }
            case "receive" => {
                // Make a copy to avoid external modification
                let copy = HashMap<String, Any>()
                for (k, v) in receive_struct {
                    copy.add(k, v)
                }
                return Some<HashMap<String, Any>>(copy)
            }
            case _ => return None<HashMap<String, Any>>()
        }
    }
}

import std.collection.HashMap

interface Equatable<T> {
    operator func == (that: T): Bool
    operator func != (that: T): Bool
}

class Item <: Equatable<Item> {
    var price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {
    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            let existing = items[item]!
            let newQuantity = existing.quantity + quantity
            items[item] = Item(price: price, quantity: newQuantity)
        } else {
            items[item] = Item(price: price, quantity: quantity)
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            let existing = items[item]!
            let remainingQuantity = existing.quantity - quantity
            if (remainingQuantity > 0) {
                items[item] = Item(price: existing.price, quantity: remainingQuantity)
            } else {
                items.remove(item)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (key, value) in items {
            total += value.price * Float64(value.quantity)
        }
        return total
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {
    let users: HashMap<String, Bool>

    public init() {
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        if (users.contains(username)) {
            return false
        }
        users.add(username, false)
        return true
    }

    public func sign_in(username: String): Bool {
        if (!users.contains(username)) {
            return false
        }
        users[username] = true
        return true
    }

    public func check_sign_in(username: String): Bool {
        if (!users.contains(username)) {
            return false
        }
        return users[username]!
    }

    public func all_signed_in(): Bool {
        for (user in users.keys) {
            if (!users[user]!) {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        let notSignedIn = ArrayList<String>()
        for (user in users.keys) {
            if (!users[user]!) {
                notSignedIn.add(user)
            }
        }
        return notSignedIn
    }
}

import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let new_x = head[0] + direction[0]
        let new_y = head[1] + direction[1]
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if new head position is out of bounds
        if (new_x < 0 || new_x >= this.SCREEN_WIDTH || new_y < 0 || new_y >= this.SCREEN_HEIGHT) {
            this.reset()
            return
        }

        // Check if new head position collides with body
        for (pos in this.positions.sublist(1, this.positions.size)) {
            if (pos[0] == new_x && pos[1] == new_y) {
                this.reset()
                return
            }
        }

        // Check if eating food
        let eating_food = new_x == this.food_position[0] && new_y == this.food_position[1]

        // Update positions
        this.positions.insert(new_head, at: 0)
        if (!eating_food) {
            this.positions.remove(at: this.positions.size - 1)
        } else {
            this.eat_food()
        }
    }

    public func random_food_position(): Unit {
        let rnd = Random()
        var valid_position = false
        var new_pos: ArrayList<Int64>

        while (!valid_position) {
            new_pos = ArrayList<Int64>([
                rnd.nextInt(0, this.SCREEN_WIDTH),
                rnd.nextInt(0, this.SCREEN_HEIGHT)
            ])

            valid_position = true
            for (pos in this.positions) {
                if (pos[0] == new_pos[0] && pos[1] == new_pos[1]) {
                    valid_position = false
                    break
                }
            }
        }

        this.food_position = new_pos
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
