class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = Regex(r"(?<=[.?!])\s+(?=[A-Z])|(?<=[.?!])\s+(?=\S)")
        let sentences = pattern.split(sentences_string)

        // Handle cases where punctuation is immediately followed by word without space
        // (though regex should handle basic cases)
        var result = ArrayList<String>()
        for s in sentences {
            if !s.isEmpty() {
                // Ensure we don't have empty strings in result
                result.add(s)
            }
        }
        return result
    }

    public func count_words(sentence: String): Int64 {
        // Simple word count by splitting on whitespace and filtering non-words
        let words = sentence.split(r"\s+")
        var count: Int64 = 0

        for word in words {
            if word.isNotEmpty() {
                // Filter out punctuation and numbers (simple check)
                let isWord = word.all { c => c.isLetter() }
                if isWord {
                    count += 1
                }
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = this.split_sentences(sentences_string: sentences_string)
        var maxCount: Int64 = 0

        for sentence in sentences {
            let count = this.count_words(sentence: sentence)
            if count > maxCount {
                maxCount = count
            }
        }
        return maxCount
    }
}

