import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = data.clone()
        sort(sorted)
        let mid = sorted.size / 2
        if (sorted.size % 2 == 0) {
            return (sorted[mid-1] + sorted[mid]) / 2.0
        } else {
            return sorted[mid] * 1.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let num = data[i]
            if (freq.contains(num)) {
                freq[num] = freq[num] ? + 1
            } else {
                freq[num] = 1
            }
        }

        var maxCount = 0
        var modes = ArrayList<Int64>()
        for (i in 0..data.size) {
            let num = data[i]
            let count = freq[num] ?? 0
            if (count > maxCount) {
                maxCount = count
                modes = ArrayList<Int64>([num])
            } else if (count == maxCount) {
                modes.add(num)
            }
        }

        // Get first mode if all elements are unique
        if (maxCount == 1) {
            return ArrayList<Int64>([data[0]])
        }

        // Filter to only include elements with maxCount
        let result = ArrayList<Int64>()
        for (num in freq.keys()) {
            if (freq[num] == maxCount) {
                result.add(num)
            }
        }
        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let meanX = mean(x) ?? 0.0
        let meanY = mean(y) ?? 0.0

        var numerator = 0.0
        var sumX2 = 0.0
        var sumY2 = 0.0

        for (i in 0..x.size) {
            let xDiff = (x[i] - meanX) * 1.0
            let yDiff = (y[i] - meanY) * 1.0
            numerator += xDiff * yDiff
            sumX2 += xDiff * xDiff
            sumY2 += yDiff * yDiff
        }

        if (sumX2 == 0.0 || sumY2 == 0.0) {
            return Some<Float64>(0.0)
        }

        let denominator = sqrt(sumX2) * sqrt(sumY2)
        if (denominator == 0.0) {
            return None<Float64>()
        }

        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i] * 1.0
        }
        return Some<Float64>(sum / data.size)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                if (i == j) {
                    row.add(1.0)
                } else {
                    let corr = correlation(data[i], data[j])
                    row.add(corr ?? 0.0)
                }
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanVal = mean(data) ?? 0.0
        if (data.size <= 1) {
            return None<Float64>()
        }
        var sumSquaredDiff = 0.0
        for (i in 0..data.size) {
            let diff = (data[i] - meanVal) * 1.0
            sumSquaredDiff += diff * diff
        }
        let variance = sumSquaredDiff / (data.size - 1)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanVal = mean(data)
        let stdVal = standard_deviation(data)

        if (meanVal == None<Float64>() || stdVal == None<Float64>()) {
            return None<ArrayList<Float64>>()
        }

        let m = meanVal.getOrThrow()
        let s = stdVal.getOrThrow()

        if (s == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let result = ArrayList<Float64>()
        for (i in 0..data.size) {
            result.add((data[i] - m) / s)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

