class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board.size || col < 0 || col >= board[0].size) {
            return false
        }
        if (this.board[row][col] != ' ') {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if (this.current_player == 'X') { 'O' } else { 'X' }
        return true
    }

    public func check_winner(): Option<String> {
        let N = this.board.size
        // Check rows
        for (i in 0..N) {
            let first = this.board[i][0]
            if (first != ' ') {
                var win = true
                for (j in 1..N) {
                    if (this.board[i][j] != first) {
                        win = false
                        break
                    }
                }
                if (win) {
                    return Some<String>(first)
                }
            }
        }
        // Check columns
        for (j in 0..N) {
            let first = this.board[0][j]
            if (first != ' ') {
                var win = true
                for (i in 1..N) {
                    if (this.board[i][j] != first) {
                        win = false
                        break
                    }
                }
                if (win) {
                    return Some<String>(first)
                }
            }
        }
        // Check diagonals
        let first_diag = this.board[0][0]
        if (first_diag != ' ') {
            var win = true
            for (i in 1..N) {
                if (this.board[i][i] != first_diag) {
                    win = false
                    break
                }
            }
            if (win) {
                return Some<String>(first_diag)
            }
        }
        let second_diag = this.board[0][N-1]
        if (second_diag != ' ') {
            var win = true
            for (i in 1..N) {
                if (this.board[i][N-1-i] != second_diag) {
                    win = false
                    break
                }
            }
            if (win) {
                return Some<String>(second_diag)
            }
        }
        return None<String>()
    }

    public func is_board_full(): Bool {
        let N = this.board.size
        for (i in 0..N) {
            for (j in 0..N) {
                if (this.board[i][j] == ' ') {
                    return false
                }
            }
        }
        return true
    }
}

