            sum = sum + term
        }
        return sum
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = this.cos(x)
        if (abs.f64(cos_val - 0.0) > 0.000001) {
            let sin_val = this.sin(x)
            return Some<Float64>(sin_val / cos_val)
        } else {
            return None<Float64>
        }
    }
}

