import std.collection.HashMap

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }
        let scheme = url.substring(0, scheme_end)
        return Some<String>(scheme)
    }

    public func get_host(): Option<String> {
        let scheme_end = url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }
        let host_start = scheme_end + 3
        var host_end = url.indexOf("/", start: host_start)
        if (host_end == -1) {
            host_end = url.indexOf("?", start: host_start)
        }
        if (host_end == -1) {
            host_end = url.indexOf("#", start: host_start)
        }
        if (host_end == -1) {
            host_end = url.size
        }
        let host = url.substring(host_start, host_end)
        return Some<String>(host)
    }

    public func get_path(): Option<String> {
        let host_end = get_path_start()
        if (host_end == -1) {
            return None<String>
        }
        var path_end = url.indexOf("?", start: host_end)
        if (path_end == -1) {
            path_end = url.indexOf("#", start: host_end)
        }
        if (path_end == -1) {
            path_end = url.size
        }
        let path = url.substring(host_end, path_end)
        return Some<String>(path)
    }

    private func get_path_start(): Int64 {
        let scheme_end = url.indexOf("://")
        if (scheme_end == -1) {
            return -1
        }
        let host_start = scheme_end + 3
        var host_end = url.indexOf("/", start: host_start)
        if (host_end == -1) {
            host_end = url.indexOf("?", start: host_start)
        }
        if (host_end == -1) {
            host_end = url.indexOf("#", start: host_start)
        }
        if (host_end == -1) {
            return -1
        }
        return host_end
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.indexOf("?")
        if (query_start == -1) {
            return None<HashMap<String, String>>
        }
        let fragment_start = url.indexOf("#", start: query_start)
        var query_end = fragment_start
        if (fragment_start == -1) {
            query_end = url.size
        }
        let query_str = url.substring(query_start + 1, query_end)
        if (query_str.size == 0) {
            return Some<HashMap<String, String>>(HashMap<String, String>())
        }

        let pairs = query_str.split("&")
        var params = HashMap<String, String>()
        for (i in 0..<pairs.size) {
            let pair = pairs[i]
            let kv = pair.split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            } else {
                params.add(kv[0], "")
            }
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.indexOf("#")
        if (fragment_start == -1) {
            return None<String>
        }
        let fragment = url.substring(fragment_start + 1, url.size)
        return Some<String>(fragment)
    }
}

