class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        var dot_product: Float64 = 0.0
        var norm_1: Float64 = 0.0
        var norm_2: Float64 = 0.0

        if (vector_1.size != vector_2.size) {
            panic("Vectors must be of equal length")
        }

        for (i in 0..vector_1.size) {
            let val_1 = vector_1[i]
            let val_2 = vector_2[i]
            dot_product += val_1 * val_2
            norm_1 += val_1 * val_1
            norm_2 += val_2 * val_2
        }

        let norm = sqrt(norm_1) * sqrt(norm_2)
        if (norm == 0.0) {
            return 0.0
        }

        return dot_product / norm
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        var results = ArrayList<Float64>()
        for (vec in vectors_all) {
            results.add(similarity(vector_1, vec))
        }
        return results
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            return 0.0
        }

        var norm_1: Float64 = 0.0
        var norm_2: Float64 = 0.0
        var dot_product: Float64 = 0.0

        for (vec1 in vector_list_1) {
            for (vec2 in vector_list_2) {
                if (vec1.size != vec2.size) {
                    panic("All vectors must be of equal length")
                }

                for (i in 0..vec1.size) {
                    dot_product += vec1[i] * vec2[i]
                }
                for (val in vec1) {
                    norm_1 += val * val
                }
                for (val in vec2) {
                    norm_2 += val * val
                }
            }
        }

        let norm = sqrt(norm_1) * sqrt(norm_2)
        if (norm == 0.0) {
            return 0.0
        }

        let total_pairs = vector_list_1.size * vector_list_2.size
        return dot_product / (norm * total_pairs as Float64)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        var result = HashMap<String, Float64>()
        for (key, count) in number_dict) {
            let weight = log((total_num + 1) as Float64 / (count + 1))
            result.add(key, weight)
        }
        return result
    }
}

