class VendingMachine {
    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        let product = Product(price: price, quantity: quantity)
        this.inventory.add(item_name, product)
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        let product_option = this.inventory.get(item_name)
        match (product_option) {
            case Some(product) => {
                if (product.quantity > 0) {
                    if (this.balance >= product.price) {
                        this.balance -= product.price
                        product.quantity -= 1
                        return Some<Float64>(this.balance)
                    } else {
                        return None<Float64>
                    }
                } else {
                    return None<Float64>
                }
            }
            case _ => return None<Float64>
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        let product_option = this.inventory.get(item_name)
        match (product_option) {
            case Some(product) => {
                product.quantity += quantity
                return true
            }
            case _ => return false
        }
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None<String>
        }

        var result = ArrayList<String>()
        for (entry in this.inventory) {
            match (entry.value) {
                case Some(product) => {
                    let item_str = "${entry.key} - $${product.price} [${product.quantity}]"
                    result.add(item_str)
                }
                case _ => Unit
            }
        }

        // Join all strings with newlines (simple implementation)
        var joined = ""
        for (i in 0..result.size) {
            joined += result[i]
            if (i < result.size - 1) {
                joined += "\n"
            }
        }

        return Some<String>(joined)
    }
}

