        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        let weather_data = weather_list[this.city]
        match (weather_data) {
            case Some<Weather>(wd) => {
                let (temp, weather_str) = if (tmp_units == "celsius" && wd.temperature_units == "fahrenheit") {
                    let temp_c = this.fahrenheit_to_celsius(temp: wd.temperature)
                    (temp_c, wd.weather)
                } else if (tmp_units == "fahrenheit" && wd.temperature_units == "celsius") {
                    let temp_f = this.celsius_to_fahrenheit(temp: wd.temperature)
                    (temp_f, wd.weather)
