        let parts = textnum.split("-")
        var total = 0
        var current = 0

        for (part in parts) {
            if (this.numwords.contains(part)) {
                let (scale, value) = this.numwords[part] ?? (1, 0)
                current = current * scale + value
            } else if (this.ordinal_words.contains(part)) {
                return this.ordinal_words[part].toString()
            } else {
                // Handle ordinal endings (simple case)
                var found = false
                for (ending in this.ordinal_endings) {
                    if (part.endsWith(ending[0])) {
                        let base = part[0..(part.size - ending[0].size)] + ending[1]
                        if (this.numwords.contains(base)) {
                            let (scale, value) = this.numwords[base] ?? (1, 0)
                            return value.toString()
                        }
                        found = true
                        break
                    }
                }
                if (!found) {
                    return "0" // Invalid input
                }
            }

            // Handle scale words (thousand, million, etc.)
            // This is simplified - actual implementation would need more logic
            if (this.scales.contains(part)) {
                continue
            }
        }

        total += current
        return total.toString()
    }

    public func is_valid_input(textnum: String): Bool {
        let parts = textnum.split("-")
        for (part in parts) {
            if (!(this.numwords.contains(part) || this.ordinal_words.contains(part))) {
                var found = false
                for (ending in this.ordinal_endings) {
                    if (part.endsWith(ending[0])) {
                        let base = part[0..(part.size - ending[0].size)] + ending[1]
                        if (this.numwords.contains(base)) {
                            found = true
                            break
                        }
                    }
                }
                if (!found) {
                    return false
                }
            }
        }
        return true
    }
